  if (g.waterType) out.push('Water: ' + g.waterType + (g.waterProfileKey ? ' (' + g.waterProfileKey + ')' : ''));
  if (g.filter) out.push('Filter: ' + g.filter);
  if (g.kettle) out.push('Kettle: ' + g.kettle);
  if (g.scale) out.push('Scale: ' + g.scale);
