  if (r.totalSecs) t.push('total time ' + _btFmtTime(r.totalSecs));
  if (t.length){ const s = t.join(', '); lines.push(s.charAt(0).toUpperCase() + s.slice(1)); }
  lines.push(SHARE_FOOT);
