    date:priceDate(o.date, true), dose:dose > 0 && dose <= 200 ? dose : null, cups:cups > 0 && cups <= 100 ? cups : null,
    roast:roastDateVal, finished:priceDate(o.finished, false), city:priceText(o.city, 60), state:priceText(o.state, 60),
