  if (grinderKey === '1zpresso-zp6') return { id:'unimodal_conical', phiFBase:0.072, sigmaC:0.27, spanNom:1.02 };
  const archKey = GRINDER_ARCHETYPE_MAP[grinderKey] || (grinderKey === 'blade' ? 'blade' : 'classic_conical');
