const RAW_BAG_GLOSSARY = [
  ['Single origin', 'From one country, and sometimes one farm or lot. A blend combines coffees from several places.'],
  ['Lot or micro-lot', 'A specific batch from one producer, often small. Different lots from the same farm can taste different.'],
  ['Farm, estate, washing station, cooperative', 'Who grew or processed it. In many countries, small farmers deliver cherries to a shared washing station or cooperative.'],
  ['Altitude (masl)', 'Meters above sea level. 1 meter is about 3.3 feet. Higher often means larger beans and brighter acidity, but elevation is only a loose guide.'],
  ['Crop year or harvest', 'When it was picked. Fresher green coffee usually tastes better.'],
  ['Roast date vs. best-by', 'The roast date tells you how fresh it is. A best-by date is usually months away and does not tell you when it peaked.'],
  ['Tasting notes', 'The roaster\'s impressions of the cup, such as "blueberry and jasmine." They are flavors you may notice, not added ingredients.'],
  ['Grades (AA, Supremo, SHB)', 'These usually describe bean size (Kenya AA, Colombia Supremo) or growing altitude (SHB). They are not a quality score.'],
  ['Peaberry', 'A cherry that holds one round seed instead of two flat ones. Some people find it a little brighter, though the evidence is mixed.'],
  ['Certifications', 'Organic, Fair Trade, and similar labels describe farming or trade practices, not flavor.'],
  ['Direct trade', 'The roaster buys straight from the producer. The exact terms vary from roaster to roaster.'],
  ['SCA score (for example 86)', 'A quality score from trained SCA tasters. 80 or above was long used as the cut-off for specialty. The SCA now defines specialty more broadly.']
];

function varietyFor(text){
  const t = norm(text); if (!t.trim()) return null;
  for (const v of VARIETIES){
    for (const a of v.aliases){ if (new RegExp('(^|[^a-z0-9])' + escRe(a) + '([^a-z0-9]|$)').test(t)) return v; }
  }
  return null;
}
function guideFor(c, now){
  const p = profileOf(c, now);
  /* the name is only a fallback when no origin is typed: a typed origin with no detailed guide (Jamaica, say) must not be replaced by a country that appears in the coffee's name */
  const origin = originFor(c.origin) || (String(c.origin || '').trim() ? null : originFor(c.name, { fuzzy:false }));
  const variety = varietyFor(c.varietal) || varietyFor(c.name), varieties = varietiesFor(c.varietal);
  if (!varieties.length && variety) varieties.push(variety);
  const proc = p.process !== 'unknown' ? (PROCESS_GUIDE[p.process] || null) : null;
  const rg = ROAST_GUIDE[p.roast] || ROAST_GUIDE.medium;
  const parts = [];
  if (origin && origin.key !== 'africa') parts.push(origin.name + ' coffees tend to be ' + origin.short + '.');
  if (proc) parts.push(proc.name + ' processing usually means ' + proc.short + '.');
  parts.push('At a ' + (labelOf(ROASTS, p.roast) || 'medium').toLowerCase() + ' roast, expect ' + rg.short + '.');
  if (p.decaf) parts.push('Decaf has higher cellular porosity and extracts rapidly.');
  if (p.density === 'high') parts.push('Grown high, so expect denser seeds and brighter acidity.');
  if (p.density === 'low') parts.push('Grown lower, the beans are softer, so expect a mellower cup.');
  let compareDefault = null;
  if (origin) compareDefault = origin.region === 'Africa' ? 'colombia' : 'africa';
  if (origin && origin.key === 'africa') compareDefault = 'colombia';
  return { profile:p, origin, variety, varieties, process:proc, roast:rg, elev:ELEV_GUIDE[p.density] || ELEV_GUIDE.unknown, summary:parts.join(' '), compareDefault };
}
function originLabel(o){ return o.key === 'africa' ? 'East Africa' : o.name; }
function compareOrigins(aKey, bKey){
  const a = ORIGINS.find(o => o.key === aKey), b = ORIGINS.find(o => o.key === bKey);
  if (!a || !b) return null;
  const an = originLabel(a), bn = originLabel(b);
  return {
    a, b,
    rows:[['Typical cup', a.feel, b.feel], ['Where it grows', a.grown, b.grown], ['Usual processing', a.process, b.process], ['Common varieties', a.varieties, b.varieties]],
    why:[
      'Plant variety: ' + an + ' commonly grows ' + a.varShort + ', while ' + bn + ' commonly grows ' + b.varShort + '. Different varieties push flavor in different directions.',
      'Growing place: ' + an + ' coffee comes from ' + a.placeShort + '. ' + bn + ' coffee comes from ' + b.placeShort + '. Altitude, climate, and soil change how the cherries ripen, and how sweet and bright the coffee turns out.',
      'Processing: ' + an + ' coffee is ' + a.procShort + '. ' + bn + ' coffee comes from ' + b.procShort + '. Processing alone changes clarity, sweetness, and body.'
    ]
  };
}

/* ---------- Phase 2 Smart Bag Parsers & 4-Tier Lookup Engine ---------- */
const INDONESIA_WORDS = /indonesia|sumatra|sulawesi|flores|timor|bali|aceh|gayo|toraja|mandheling|lintong|papua/;

/* Fixes BUG-PRS-07: Multi-stage process, Honey tiers, Thermal Shock, Yeast/Koji, Co-ferments, Decaf chemistries, & tasting-note honey guard */
function readProcessV2(t, origin){
  const raw = String(t || '').trim(), s = norm(raw);
  const none = { value:'', base:'', mods:[], honeyTier:'', decafProcess:'', how:'none', note:'', display:'' };
  if (!s) return none;

  /* Detect decaffeination chemistry even if embedded in process field */
  let decafProcess = '';
  if (/\be\.?a\.?\s+decaf|ethyl\s+acetate|sugar\s*cane(?:\s+decaf)?|\bcana\s+decaf/i.test(s)) decafProcess = 'ea';
  else if (/swiss\s+water|\bswp\b/i.test(s)) decafProcess = 'swiss';
  else if (/mountain\s+water|\bmwp\b/i.test(s)) decafProcess = 'mountain';
  else if (/(?:supercritical\s+|subcritical\s+|liquid\s+)?co2(?:\s+decaf)?|carbon\s+dioxide\s+decaf/i.test(s)) decafProcess = 'co2';
  else if (/methylene\s+chloride|\bdcm\s+decaf\b/i.test(s)) decafProcess = 'mc';

  /* Extract fermentation / experimental modifiers */
  const mods = [];
  if (/\bco[- ]?ferment|fruit[- ]?infus|infused\s+with|macerated\s+with|\binfused\b/i.test(s)) mods.push('co-ferment');
  if (/thermal[- ]?shock|choque\s*t[eé]rmico/i.test(s)) mods.push('thermal-shock');
  if (/carbonic(?:\s+maceration)?|\bcm\s+(?:washed|natural|honey|process)\b|\bcm\b/i.test(s)) mods.push('carbonic');
  if (/anaerob|anoxic/i.test(s)) mods.push('anaerobic');
  if (/\bkoji\b|aspergillus|yeast[- ]?inoculat|selected\s+yeast|saccharomyces|bioreactor/i.test(s)) mods.push('yeast-koji');
  if (/\blactic\b/i.test(s)) mods.push('lactic');
  if (/\bmosto\b/i.test(s)) mods.push('mosto');
  if (/extended\s+ferment|controlled\s+ferment|\b(?:36|48|60|72|96|120|144|180|200)\s*h(?:r|rs|our|ours)?\s*(?:ferment|anaerob|macerat)/i.test(s)) mods.push('extended');

  /* Guard against tasting-note honey words when parsing unstructured prose */
  const cleanForHoney = s.replace(/\b(?:wildflower|clover|orange\s+blossom|acacia|manuka|tupelo|buckwheat|raw|floral|sweet)\s+honey\b/g, ' ')
    .replace(/\bhoney\s*(?:crisp|dew|suckle|comb|sweetness|notes?|like)\b/g, ' ');

  let base = '', honeyTier = '', how = 'sure', note = '';
  const hm = /\b(white|yellow|gold(?:en)?|red|black)\s*(?:honey|miel)\b/.exec(cleanForHoney);
  if (hm){
    honeyTier = hm[1].indexOf('gold') === 0 ? 'yellow' : hm[1];
    base = honeyTier + '-honey';
  } else if (/\b(?:honey|miel)\b|pulped[- ]?natural|pulp[- ]?natural|descascado|cereja\s+descascado/.test(cleanForHoney)){
    base = 'honey';
  } else if (/wet[- ]?hull|giling\s*basah/.test(s)){
    base = 'wet-hulled';
  } else if (/semi[- ]?wash|partial(?:ly)?[- ]?wash|half[- ]?wash/.test(s)){
    if (INDONESIA_WORDS.test(norm(origin || ''))){
      base = 'wet-hulled'; how = 'guess';
      note = 'Semi-washed on an Indonesian coffee usually means wet-hulled (Giling Basah).';
    } else {
      how = 'ambiguous';
      note = 'Semi-washed can mean wet-hulled (Indonesia) or pulped natural / short-ferment washed.';
    }
  } else if (/\bnaturals?\b|dry[- ]?process|sun[- ]?dried\s+cherry|whole[- ]?cherry|\bunwashed\b|monsoon/.test(s)){
    base = 'natural';
    if (/monsoon/.test(s)) note = 'Monsooned dry-processed coffee exposed to humid monsoon winds.';
  } else if (/double[- ]?wash|kenya[- ]?style|\b(?:48|72)[- ]?h(?:r|our)?\s*wash|\b(?:fully\s+)?washed\b|\bwet[- ]?process(?:ed)?\b|\bwahsed\b|\blavado\b/.test(s)){
    base = 'washed';
  }

  let value = base;
  if (mods.includes('co-ferment')) value = 'infused';
  else if (mods.includes('thermal-shock')) value = 'thermal-shock';
  else if (mods.includes('carbonic')) value = 'carbonic';
  else if (mods.includes('yeast-koji')) value = 'yeast-koji';
  else if (mods.includes('anaerobic') || mods.includes('lactic') || mods.includes('extended') || mods.includes('mosto')) value = 'anaerobic';

  if (!value && how !== 'ambiguous' && !decafProcess) return none;
  if (base && value && base !== value){
    note = ('Multi-stage process detected: ' + mods.join(', ') + ' on a ' + base.replace('-', ' ') + ' base.').replace(/\s+/g, ' ');
  }
  const displayParts = [];
  if (mods.length) displayParts.push(mods.map(m => m.replace(/(^|-)\w/g, c => c.toUpperCase())).join(' '));
  if (base && (!mods.length || !value.includes(base))) displayParts.push(labelOf(PROCESSES, base) || base);
  return { value, base, mods, honeyTier, decafProcess, how, note, display:displayParts.join(' · ') || (value ? labelOf(PROCESSES, value) : '') };
}
function readProcess(t, origin){ return readProcessV2(t, origin); }
function mapProcess(t, origin){ return readProcessV2(t, origin).value; }

/* Fixes BUG-PRS-05 & BUG-PRS-06: Strips roast legends & negations first; supports Nordic, Ultra-Light, Omni, Filter, Espresso, City..Italian, Agtron #, X/5 */
function mapRoastV2(t, agtronVal){
  let s = norm(t);
  if (!s && agtronVal != null && isFinite(+agtronVal) && +agtronVal > 0){
    const av = +agtronVal;
    if (typeof G.agtronToRoastKey === 'function') return G.agtronToRoastKey(av);
    return av >= 86 ? 'ultra-light' : av >= 74 ? 'light' : av >= 64 ? 'medium-light' : av >= 53 ? 'medium' : av >= 42 ? 'medium-dark' : 'dark';
  }
  if (!s) return '';
  /* 1. Strip printed scale legends like "Light | Medium | Dark" or "Light - Medium - Dark" */
  s = s.replace(/\b(?:ultra[- ]?light\s*[|•\/\-–—>]+\s*)?light\s*[|•\/\-–—>]+\s*(?:medium[- ]?light\s*[|•\/\-–—>]+\s*)?medium\s*[|•\/\-–—>]+\s*(?:medium[- ]?dark\s*[|•\/\-–—>]+\s*)?dark\b/gi, ' ');
  /* 2. Strip negated clauses like "not dark", "never too dark", "without dark roast bitterness" */
  s = s.replace(/\b(?:not|never|no|neither|without(?:\s+any|\s+being)?)\s+(?:too\s+|overly\s+|very\s+)?(?:ultra[- ]?light|nordic|medium[- ]?dark|medium[- ]?light|dark|medium|light|french|italian|roasty)\b/gi, ' ');
  /* 3. Agtron Gourmet / Commercial numbers (aligned with 01:agtronToRoastKey 86/74/64/53/42) */
  const ag = /\bagtron(?:\s+gourmet)?\s*[:#=\-]?\s*(\d{2,3}(?:\.\d)?)\b/.exec(s);
  if (ag){
    const n = +ag[1];
    if (n >= 20 && n <= 115){
      if (typeof G.agtronToRoastKey === 'function') return G.agtronToRoastKey(n);
      if (n >= 86) return 'ultra-light';
      if (n >= 74) return 'light';
      if (n >= 64) return 'medium-light';
      if (n >= 53) return 'medium';
      if (n >= 42) return 'medium-dark';
      return 'dark';
    }
  }
  /* 4. Numeric scale ratios like "Roast: 2/5" or "1/6" */
  const sc = /\broast(?:\s+level|\s+degree|\s+profile)?\s*[:\-]?\s*([1-6])\s*(?:\/|of|out\s+of)\s*([56])\b/.exec(s);
  if (sc){
    const num = +sc[1], den = +sc[2];
    if (den === 6) return ['ultra-light', 'light', 'medium-light', 'medium', 'medium-dark', 'dark'][num - 1] || '';
    return ['light', 'medium-light', 'medium', 'medium-dark', 'dark'][Math.min(4, num - 1)] || '';
  }
  /* 5. Specialty & traditional vocabulary in unambiguous specificity order */
  if (/\bultra[- ]?light\b|\bextra[- ]?light\b|\bnordic\b|\bscandinavian\b|\bcinnamon\s+roast\b/.test(s)) return 'ultra-light';
  if (/\bmedium[- /]?dark\b|\bfull[- ]?city\s*\+|\bfull[- ]?city\s+plus\b|\bvienna\b|\bviennese\b/.test(s)) return 'medium-dark';
  if (/\bmedium[- /]?light\b|\blight[- /]?medium\b|\blight\s+to\s+medium\b|\bomni(?:[- ]?roast)?\b|\bmodern\s+espresso\b|\bnew\s+england\b|\bhalf[- ]?city\b/.test(s)) return 'medium-light';
  if (/\bfrench(?:\s+roast)?\b|\bitalian(?:\s+roast)?\b|\bspanish(?:\s+roast)?\b|\btraditional\s+espresso\b|\bdark\b/.test(s)) return 'dark';
  if (/\bcity\s*\+|\bcity\s+plus\b|\bfull[- ]?city\b|\bamerican\s+roast\b|\bespresso\s+roast\b|\bmedium\b/.test(s)) return 'medium';
  if (/\bfilter\s+roast\b|\bpour[- ]?over\s+roast\b|\bblonde\b|\blight\b/.test(s)) return 'light';
  if (/(^|[^a-z])cinnamon([^a-z]|$)/.test(s) && !/apple|roll|toast|clove|cardamom|nutmeg|sugar|spice/.test(s)) return 'ultra-light';
  if (/(^|[^a-z])city([^a-z]|$)/.test(s)) return 'medium-light';
  if (/^\s*filter\s*$/.test(s)) return 'light';
  if (/^\s*espresso\s*$/.test(s)) return 'medium';
  return '';
}
function mapRoast(t, agtronVal){ return mapRoastV2(t, agtronVal); }

/* Fixes BUG-PRS-01..04: Dual-unit "1,800 m (5,905 ft)" -> 1800 (never averaged to 1174!), Spanish/Euro "1.850 msnm" -> 1850, lot/year stripping, 100m island floor */
function mapElevationV2(t){
  let s = String(t == null ? '' : t).trim();
  if (!s) return { m:null, ft:null, cls:'', band:'' };
  /* Normalize European/Spanish period-thousands (e.g. "1.850 msnm", "1.700 - 2.000 m.s.n.m.") before decimal parsing */
  s = s.replace(/\b([1-9])\s*\.\s*(\d{3})(?!\d)/g, '$1$2').replace(/\b(1\d)\s*\.\s*(\d{3})(?!\d)/g, '$1$2');
  /* Strip parenthetical secondary unit conversions when primary unit sits outside parens: e.g. "1,800 m (5,905 ft)" or "5,905 ft (1,800 m)" */
  const sNoParen = s.replace(/\([^)]*\b(?:ft|feet|foot|fasl|masl|msnm|meters?|metres?|m)\b[^)]*\)/gi, ' ');

  const parseSpan = (str, unitRe, isFeet) => {
    const rx = new RegExp('(\\d[\\d,]{1,4})(?:\\s*(?:[-–—~]|to)\\s*(\\d[\\d,]{1,4}))?\\s*(?:' + unitRe + ')(?![a-z])', 'gi');
    let m;
    while ((m = rx.exec(str))){
      const a = +m[1].replace(/,/g, ''), b = m[2] ? +m[2].replace(/,/g, '') : null;
      const hiLim = isFeet ? 12000 : 3600, loLim = isFeet ? 300 : 100;
      if (a >= loLim && a <= hiLim && (b == null || (b >= loLim && b <= hiLim))){
        const avg = b != null ? (a + b) / 2 : a;
        return Math.round(isFeet ? avg * 0.3048 : avg);
      }
    }
    return null;
  };

  const METER_UNITS = 'm\\.?a\\.?s\\.?l\\.?|mamsl|m\\.?s\\.?n\\.?m\\.?|meters?|metres?|metros|m';
  const FEET_UNITS = 'f\\.?a\\.?s\\.?l\\.?|feet|foot|ft';

  /* 1. Try meter-anchored span in parenthetical-stripped string, then full string (prioritizing meters on dual-unit strings!) */
  let mVal = parseSpan(sNoParen, METER_UNITS, false);
  if (mVal == null) mVal = parseSpan(s, METER_UNITS, false);
  /* 2. Try feet-anchored span */
  if (mVal == null) mVal = parseSpan(sNoParen, FEET_UNITS, true);
  if (mVal == null) mVal = parseSpan(s, FEET_UNITS, true);

  /* 3. Fallback for bare numeric elevation (e.g. typed "1850" or "1800-2000" in an elevation field), after stripping years & lot #s */
  if (mVal == null){
    const cleaned = sNoParen
      .replace(/\b(?:harvest|crop|lot|batch|picked|roast(?:ed)?|year|est\.?|since|founded|#)\s*[:#-]?\s*\d+(?:[\/\-]\d+)?/gi, ' ')
      .replace(/\b20[123]\d\s*\/\s*(?:20)?[123]\d\b/g, ' ');
    const hasFeetWord = /(^|[^a-z])(ft|feet|foot|fasl)([^a-z]|$)/i.test(cleaned);
    const hasMeterWord = /(\d\s*m\b)|(^|[^a-z])(masl|msnm|meters?|metres?|metros)([^a-z]|$)/i.test(cleaned);
    let nums = (cleaned.replace(/,/g, '').match(/\d+(?:\.\d+)?/g) || []).map(Number).filter(n => n >= 150 && n <= 11500);
    /* If there are >=2 numbers and one looks like a calendar year 2020..2030 while not an obvious range (like 1950-2050), drop standalone year unless paired with dash */
    if (nums.length >= 2 && !/\d\s*[-–—~]\s*20[23]\d/.test(cleaned) && !/20[23]\d\s*[-–—~]\s*\d/.test(cleaned)){
      const nonYr = nums.filter(n => n < 2020 || n > 2032);
      if (nonYr.length) nums = nonYr;
    }
    if (nums.length){
      const v = nums.length >= 2 ? (nums[0] + nums[1]) / 2 : nums[0];
      const asFt = hasFeetWord || (!hasMeterWord && v > 3500);
      mVal = Math.round(asFt ? v * 0.3048 : v);
    }
  }

  if (mVal == null || mVal < 100 || mVal > 3500) return { m:null, ft:null, cls:'', band:'' };
  return {
    m:mVal,
    ft:Math.round(mVal / 0.3048),
    cls:mVal >= 1500 ? 'high' : mVal >= 1200 ? 'mid' : 'low',
    band:mVal >= 1850 ? 'very-high' : mVal >= 1450 ? 'high' : mVal >= 1000 ? 'mid' : 'low'
  };
}
function mapElevation(t){ return mapElevationV2(t); }

/* Fixes BUG-PRS-08: Flexible date parser with future-date guard */
const MONTH_IDX = { jan:1, january:1, feb:2, february:2, mar:3, march:3, apr:4, april:4, may:5, jun:6, june:6, jul:7, july:7, aug:8, august:8, sep:9, sept:9, september:9, oct:10, october:10, nov:11, november:11, dec:12, december:12 };
function isoDateV2(t, now){
  const raw = String(t || '').trim(); if (!raw) return '';
  const pad = n => String(n).padStart(2, '0');
  const check = (y, mo, d) => {
    if (y < 100) y += 2000;
    if (y < 2000 || y > 2100 || mo < 1 || mo > 12 || d < 1 || d > 31) return '';
    const iso = y + '-' + pad(mo) + '-' + pad(d);
    if (typeof validIsoDate === 'function' && !validIsoDate(iso)) return '';
    const ref = now || new Date();
    const maxUtc = Date.UTC(ref.getFullYear(), ref.getMonth(), ref.getDate()) + 86400000;
    if (Date.UTC(y, mo - 1, d) > maxUtc) return ''; /* reject future dates */
    return iso;
  };
  let m = /^(\d{4})[-\/.](\d{1,2})[-\/.](\d{1,2})$/.exec(raw);
  if (m) return check(+m[1], +m[2], +m[3]);
  m = /\b([A-Za-z]{3,9})\.?\s+(\d{1,2})(?:st|nd|rd|th)?,?\s*(\d{2,4})\b/.exec(raw);
  if (m && MONTH_IDX[m[1].toLowerCase()]) return check(+m[3], MONTH_IDX[m[1].toLowerCase()], +m[2]);
  m = /\b(\d{1,2})(?:st|nd|rd|th)?\s+([A-Za-z]{3,9})\.?,?\s*(\d{2,4})\b/.exec(raw);
  if (m && MONTH_IDX[m[2].toLowerCase()]) return check(+m[3], MONTH_IDX[m[2].toLowerCase()], +m[1]);
  m = /^(\d{1,2})[\/\-](\d{1,2})[\/\-](\d{2,4})$/.exec(raw);
  if (m){
    const a = +m[1], b = +m[2], y = +m[3];
    if (a > 12 && b <= 12) return check(y, b, a);
    if (b > 12 && a <= 12) return check(y, a, b);
  }
  return '';
}
function isoDate(t){ return isoDateV2(t); }

/* Fixes BUG-PRS-09: Balanced-brace JSON object extractor tolerating prose braces, smart quotes & trailing commas */
function parseScanReplyV2(text){
  let t = String(text || '').trim(); if (!t) return null;
  t = t.replace(/```(?:json)?/gi, '').replace(/[\u201C\u201D]/g, '"').replace(/[\u2018\u2019]/g, "'");
  const candidates = [];
  for (let i = 0; i < t.length; i++){
    if (t[i] !== '{') continue;
    let depth = 0, inStr = false, esc = false;
    for (let j = i; j < t.length; j++){
      const ch = t[j];
      if (inStr){
        if (esc) esc = false;
        else if (ch === '\\') esc = true;
        else if (ch === '"') inStr = false;
      } else {
        if (ch === '"') inStr = true;
        else if (ch === '{') depth++;
        else if (ch === '}'){
          depth--;
          if (depth === 0){
            candidates.push(t.slice(i, j + 1));
            break;
          }
        }
      }
    }
  }
  const WANT = ['coffee_name', 'roaster', 'origin', 'varietal', 'process', 'roast_level', 'tasting_notes', 'elevation'];
  let fallback = null;
  for (let k = 0; k < candidates.length; k++){
    const cleaned = candidates[k].replace(/,\s*([}\]])/g, '$1');
    try {
      const o = JSON.parse(cleaned);
      if (o && typeof o === 'object' && !Array.isArray(o)){
        if (WANT.some(w => Object.prototype.hasOwnProperty.call(o, w))) return o;
        if (!fallback) fallback = o;
      }
    } catch(e){}
  }
  return fallback;
}
function parseScanReply(text){ return parseScanReplyV2(text); }

function mapScan(d){
  d = (d && typeof d === 'object' && !Array.isArray(d)) ? d : {};
  const str = v => typeof v === 'string' ? v.trim().slice(0, 300) : (typeof v === 'number' && isFinite(v) ? String(v) : '');
  const items = [];
  const text = (key, label, v) => { const s = str(v); if (s) items.push({ key, label, value:s, display:s, raw:s }); };
  text('name', 'Coffee name', d.coffee_name || d.name);
  text('roaster', 'Roaster', d.roaster || d.brand);
  text('origin', 'Origin', d.origin || [str(d.origin_region), str(d.origin_country)].filter(Boolean).join(', '));
  text('varietal', 'Varietal', Array.isArray(d.varietal) ? d.varietal.join(', ') : (d.varietal || d.variety));

  const spRaw = norm(str(d.species));
  if (spRaw && spRaw !== 'arabica'){
    const spMap = /liberica|barako/.test(spRaw) ? 'liberica' : /excelsa|dewevrei/.test(spRaw) ? 'excelsa' : /eugenioides/.test(spRaw) ? 'eugenioides' : /stenophylla/.test(spRaw) ? 'stenophylla' : /blend/.test(spRaw) ? 'blend_ar' : /robusta|canephora/.test(spRaw) ? 'robusta' : '';
    if (spMap) items.push({ key:'species', label:'Species', value:spMap, display:labelOf(SPECIES_OPTS, spMap) || spMap, raw:str(d.species) });
  }

  const pr = [str(d.process), str(d.process_base), Array.isArray(d.process_modifiers) ? d.process_modifiers.join(' ') : str(d.process_modifiers), str(d.honey_tier) ? str(d.honey_tier) + ' honey' : ''].filter(Boolean).join(' ');
  if (pr){
    const rd = readProcessV2(pr, str(d.origin || d.origin_country)), v = rd.value;
    items.push({ key:'process', label:'Process', value:v, display:v ? labelOf(PROCESSES, v) : '', raw:str(d.process) || pr, unmatched:!v, hint:rd.note });
    if (rd.decafProcess && !d.decaf_process) d.decaf_process = rd.decafProcess;
  }

  const rr = str(d.roast_level) || (d.agtron ? 'Agtron ' + str(d.agtron) : '');
  if (rr){ const v = mapRoastV2(rr); items.push({ key:'roast', label:'Roast level', value:v, display:v ? labelOf(ROASTS, v) : '', raw:rr, unmatched:!v }); }

  const er = str(d.elevation || d.altitude);
  if (er){
    const e = mapElevationV2(er);
    items.push({ key:'density', label:'Elevation', value:e.cls, elevM:e.m, display:e.cls ? labelOf(DENSITIES, e.cls) + (e.m ? ' (' + e.m + ' m / ' + e.ft + ' ft)' : '') : '', raw:e.m ? (e.m + ' masl') : er, unmatched:!e.cls });
  }

  const dt = isoDateV2(d.roast_date);
  if (dt) items.push({ key:'roast_date', label:'Roast date', value:dt, display:dt, raw:str(d.roast_date) });

  const dpRaw = norm(str(d.decaf_process || (d.caffeine_type === 'half-caf' ? 'half-caf' : '')));
  if (d.decaf === true || d.caffeine_type === 'decaf' || d.caffeine_type === 'half-caf' || dpRaw){
    const dp = /half/.test(dpRaw) || d.caffeine_type === 'half-caf' ? 'half-caf'
      : /ea|ethyl|sugar|cana/.test(dpRaw) ? 'ea'
      : /swiss|swp/.test(dpRaw) ? 'swiss'
      : /mountain|mwp/.test(dpRaw) ? 'mountain'
      : /co2|carbon/.test(dpRaw) ? 'co2'
      : /mc|methylene/.test(dpRaw) ? 'mc' : 'unknown';
    if (dp !== 'half-caf') items.push({ key:'decaf', label:'Decaf', value:'yes', display:'Decaf', raw:'decaf' });
    items.push({ key:'decaf_process', label:'Decaf process', value:dp, display:(DECAF_PROCESSES.find(x => x.v === dp) || {}).label || dp, raw:str(d.decaf_process) || dp });
  }

  const notesVal = Array.isArray(d.tasting_notes) ? d.tasting_notes.join(', ') : d.tasting_notes;
  text('bag_notes', 'Tasting notes', notesVal);

  const WEB_KEY = { coffee_name:'name', roaster:'roaster', origin:'origin', varietal:'varietal', process:'process', roast_level:'roast', elevation:'density', tasting_notes:'bag_notes', decaf:'decaf', species:'species', decaf_process:'decaf_process' };
  const web = new Set((Array.isArray(d.from_web) ? d.from_web : []).filter(x => typeof x === 'string').map(x => WEB_KEY[x.trim()] || x.trim()));
  items.forEach(it => { if (web.has(it.key) && it.key !== 'roast_date') it.web = true; });
  const sources = Array.isArray(d.sources) ? d.sources.filter(x => typeof x === 'string' && /^https:\/\/[^\s"<>]+$/.test(x.trim())).map(x => x.trim().slice(0, 300)).slice(0, 5) : [];
  const unclear = Array.isArray(d.unclear) ? d.unclear.filter(x => typeof x === 'string').map(x => x.trim().slice(0, 40)).filter(Boolean).slice(0, 12) : [];
  const bwG = parseBagWeightGrams(d.bag_weight_g != null ? d.bag_weight_g : (d.bag_weight != null ? d.bag_weight : (d.weight != null ? d.weight : d.net_weight)));
  return { items, unclear, sources, note:str(d.notes), bag_weight_g:bwG, any:items.some(i => i.value) || bwG != null };
}

