const shopKey = s => norm(s).replace(/[^a-z0-9]+/g, ' ').trim();
function shopOrigin(input){
  let s = String(input || '').trim().slice(0, 400); if (!s) return '';
  if (!/^[a-z][a-z0-9+.-]*:\/\//i.test(s)) s = 'https://' + s;
  const m = /^https?:\/\/([^\/?#\s]+)/i.exec(s); if (!m) return '';
  const host = m[1].toLowerCase().replace(/^[^@]*@/, '').replace(/:\d+$/, '');
  if (!/^[a-z0-9]([a-z0-9-]*[a-z0-9])?(\.[a-z0-9]([a-z0-9-]*[a-z0-9])?)+$/.test(host)) return '';
  if (/^[0-9.]+$/.test(host) || /\.(local|localhost|internal|lan|home|corp|test|invalid)$/.test(host)) return '';
  return 'https://' + host;
}

function roasterDomainFor(roasterName, prefsSites){
  const k = shopKey(roasterName);
  if (!k) return '';
  if (prefsSites && prefsSites[k]) return prefsSites[k];
  const hit = ROASTER_DIRECTORY.find(r => {
    const rk = shopKey(r.name), shortRk = rk.replace(/\b(?:coffee|roasters?|co|lab|company|crafted)\b/g, '').replace(/\s+/g, ' ').trim();
    return rk === k || (shortRk.length >= 3 && (k === shortRk || k.indexOf(shortRk) === 0 || rk.indexOf(k) === 0));
  });
  return hit ? 'https://' + hit.domain : '';
}

