function gcMoleculeFor(wordText, famName){
  const w = String(wordText || '').toLowerCase().replace(/^[\*\+\-]\s*/, '').replace(/^\d+\s*·?\s*/, '').trim();
  if (w && GC_MOLECULES[w]) return Object.assign({ target:w }, GC_MOLECULES[w]);
  const hitKey = w ? Object.keys(GC_MOLECULES).find(k => w.includes(k) || k.includes(w)) : '';
  if (hitKey) return Object.assign({ target:hitKey }, GC_MOLECULES[hitKey]);
  if (famName && GC_FAMILY_DEFAULTS[famName]) return Object.assign({ target:famName }, GC_FAMILY_DEFAULTS[famName]);
  return null;
}
