  const words = x => x.split(/[^a-z\u00c0-\u024f]+/).filter(Boolean);
  const hasRun = (big, small) => { const b = words(big), t = words(small); if (!t.length) return false; for (let i = 0; i + t.length <= b.length; i++) if (t.every((w, j) => b[i + j] === w)) return true; return false; };
