function suggestFromWords(table, picked){
  const items = (picked || []).map(w => table.find(x => x.w === w)).filter(Boolean);
  if (!items.length) return null;
  const level = Math.max(1, Math.min(5, Math.round(items.reduce((a, x) => a + x.level, 0) / items.length)));
  const pos = items.some(x => x.tone === 'good'), neg = items.some(x => x.tone === 'poor'), mixed = pos && neg;
  const tip = mixed ? 'These words pull in opposite directions. Trust the one you feel more strongly, and set the score yourself.'
    : (items.find(x => x.tone === 'poor') || items[items.length - 1]).tip;
  /* The words set how strong the attribute feels (level). They never set the quality score: the SCA asks for quality judged against the profile expected of this coffee, so a bright Kenya and a soft Sumatra can both deserve high scores. */
  return { level, score:null, mixed, tip };
}
