function scoreTip(key, score){
  const t = SCORE_TIPS[key]; if (!t || score == null) return '';
  return score < 7 ? t[0] : score < 8 ? t[1] : t[2];   /* tiers follow the SCA labels: Good, Very good, Excellent and up */
}

