/* the kinds, in the order the buttons show them (the first group is "All", added by the screen) */
const GL_GROUPS = ['Brewing', 'Gear', 'Drinks', 'Tasting', 'Flavors', 'Beans & farms', 'Origins', 'Processing', 'Roasting', 'On the bag', 'Water & science'];
/* older entries that name a place; they are listed under Origins */
const GL_PLACES = ['antigua', 'cerrado', 'guji', 'harrar', 'huehuetenango', 'huila', 'jamaica blue mountain', 'kona', 'mokha', 'narino', 'santos', 'sidamo', 'sulawesi', 'sumatra', 'tarrazu', 'yirgacheffe', 'java'];
