/* How a search is read, in order of strength:
   1. the whole search is the word, or the word with the spaces left out ("pourover"), or one of its other names;
   2. the word starts with the search;
   3. every typed word is found in the word, its other names, its hidden words ("expresso"), or its definition;
   4. a word is close to what was typed (one letter off, swapped letters, or the same sound).
   If nothing matches every word, the best half-matches are shown instead. */
/* words that carry no meaning in a search, dropped when something else is left */
const GL_STOP = ['a', 'an', 'the', 'is', 'are', 'of', 'in', 'to', 'for', 'and', 'or', 'how', 'what', 'whats', 'does', 'do', 'my', 'i', 'with', 'on', 'it', 'can', 'you', 'me', 'about', 'why', 'which', 'that', 'this', 'at', 'as', 'coffee', 'coffees', 'much', 'many', 'should', 'would', 'could', 'there', 'from', 'if', 'be', 'am', 'was', 'were', 'make', 'use'];
/* lower case, no accents, letters and digits only, one space between words */
function glNorm(s){
  return String(s == null ? '' : s).toLowerCase().replace(/µ/g, 'u').replace(/&/g, ' and ').normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^a-z0-9]+/g, ' ').trim();
}
/* a light stem so "washed", "washing" and "washes" meet; applied to both sides */
function glStem(w){
  if (w.length > 4 && w.endsWith('ies')) return w.slice(0, -3) + 'y';
  if (w.length > 5 && w.endsWith('ing')) return w.slice(0, -3);
  if (w.length > 4 && w.endsWith('ed')) return w.slice(0, -2);
  if (w.length > 4 && /(sh|ch|x|ss)es$/.test(w)) return w.slice(0, -2);
  if (w.length > 3 && w.endsWith('s') && !/(ss|us|is)$/.test(w)) return w.slice(0, -1);
  return w;
}
/* a rough sound of a word, so "kemex" meets "chemex" and "capuccino" meets "cappuccino" */
function glSound(w){
  return w.replace(/ph/g, 'f').replace(/ck/g, 'k').replace(/ch/g, 'k').replace(/c(?=[eiy])/g, 's').replace(/[cq]/g, 'k').replace(/z/g, 's').replace(/x/g, 'ks').replace(/(.)\1+/g, '$1');
}
/* text -> list of [word, stem, sound] */
function glWords(s){
  return glNorm(s).split(' ').filter(Boolean).map(w => [w, glStem(w), glSound(w)]);
}
/* a quick test before the slower distance: typos rarely change both the first and the last letter */
function glAlike(a, b){ return a[0] === b[0] || a[a.length - 1] === b[b.length - 1]; }
/* how many letters apart two words are (a swap of neighbours counts as one); stops early past max */
function glDist(a, b, max){
  const la = a.length, lb = b.length;
  if (Math.abs(la - lb) > max) return max + 1;
  let p2 = null, p1 = [];
  for (let j = 0; j <= lb; j++) p1.push(j);
  for (let i = 1; i <= la; i++){
    const cur = [i];
    let low = i;
    for (let j = 1; j <= lb; j++){
      let v = Math.min(p1[j] + 1, cur[j - 1] + 1, p1[j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1));
      if (p2 && i > 1 && j > 1 && a[i - 1] === b[j - 2] && a[i - 2] === b[j - 1]) v = Math.min(v, p2[j - 2] + 1);
      cur.push(v);
      if (v < low) low = v;
    }
    if (low > max) return max + 1;
    p2 = p1; p1 = cur;
  }
  return p1[lb];
}
/* build the search index for one entry (kept on the entry as .ix) */
function glPrepare(e){
  const compact = s => s.replace(/ /g, '');
  const ix = { t:glNorm(e.term), a:e.alts.map(glNorm), h:e.hidden.map(glNorm) };
  ix.tc = compact(ix.t);
  ix.ac = ix.a.map(compact);
  ix.hc = ix.h.map(compact);
  ix.tw = glWords(e.term);
  ix.aw = glWords(e.alts.join(' '));
  ix.hw = glWords(e.hidden.join(' '));
  ix.dw = glWords(e.def);
  /* all the words and stems of each list as one string: a typed word that is not inside it cannot match any word in the list, so the scan can be skipped */
  const flat = ws => ' ' + ws.map(w => w[0] + ' ' + w[1]).join(' ') + ' ';
  ix.tt = flat(ix.tw); ix.at = flat(ix.aw); ix.ht = flat(ix.hw); ix.dt = flat(ix.dw);
  e.ix = ix;
  return ix;
}
/* 2 = the same word, 1 = starts the same, 0 = no */
function glHit(q, w){
  if (w[0] === q[0] || w[1] === q[1]) return 2;
  if (w[0].startsWith(q[0]) || w[1].startsWith(q[1])) return 1;
  return 0;
}
/* the best a single typed word can do against one entry: term 60, other name 45, hidden word 35, definition 12.
   A typo is forgiven against the term's own words; with wide on it is forgiven against other names and hidden words too */
function glBest(ix, q, wide, cm){
  const n = q[0].length;
  let best = 0;
  const scan = (arr, txt, ex, pre) => {
    if (txt.indexOf(q[0]) < 0 && txt.indexOf(q[1]) < 0) return;
    for (let i = 0; i < arr.length; i++){
      const k = glHit(q, arr[i]);
      if (k === 2){ if (ex > best) best = ex; return; }
      if (k === 1 && pre > best) best = pre;
    }
  };
  scan(ix.tw, ix.tt, 60, 50);
  if (n >= 2){ scan(ix.aw, ix.at, 45, 38); scan(ix.hw, ix.ht, 35, 28); }
  if (n >= 3) scan(ix.dw, ix.dt, 12, 9);
  if (best || n < 4) return best;
  /* nothing matched: allow a typo (one letter off, two for long words) or the same sound. Short words are too easy to mistake, so only the sound is checked for them */
  const lim = n < 5 ? 0 : n < 8 ? 1 : 2;
  const close = arr => {
    for (let i = 0; i < arr.length; i++){
      const w = arr[i];
      if (Math.abs(w[0].length - n) > lim) continue;
      if (w[2] === q[2]) return 16;
      if (!lim || !glAlike(q[0], w[0])) continue;
      /* many entries share a word such as "coffee", so the distance to each distinct word is worked out once per search */
      let near = cm ? cm.get(w[0]) : undefined;
      if (near === undefined){ near = glDist(q[0], w[0], lim) <= lim; if (cm) cm.set(w[0], near); }
      if (near) return 18;
    }
    return 0;
  };
  return wide ? Math.max(close(ix.tw), close(ix.aw), close(ix.hw)) : close(ix.tw);
}
/* the score of one entry for a search, or 0 for no match. need = how many typed words must be found */
/* the word-to-word distances already worked out for one typed word during one search */
function closeMemo(memo, word){
  let c = memo.get(word);
  if (!c){ c = new Map(); memo.set(word, c); }
  return c;
}
function glScore(ix, qn, qc, qw, need, wide, memo){
  let phrase = 0;
  if (ix.t === qn) phrase = 1000;
  else if (ix.tc === qc) phrase = 960;
  else if (ix.a.indexOf(qn) >= 0 || ix.ac.indexOf(qc) >= 0) phrase = 900;
  else if (ix.t.startsWith(qn)) phrase = 800;
  else if (qc.length >= 3 && ix.tc.startsWith(qc)) phrase = 780;
  let sum = 0, hit = 0;
  /* the same word is scored against the same entry in several passes of one search, so the answer is kept for the length of that search */
  let mm = memo && memo.get(ix);
  if (memo && !mm){ mm = {}; memo.set(ix, mm); }
  qw.forEach(w => {
    const key = (wide ? 'w' : 'n') + w[0];
    let b;
    if (mm && key in mm) b = mm[key]; else { b = glBest(ix, w, wide, memo && closeMemo(memo, w[0])); if (mm) mm[key] = b; }
    if (b){ sum += b; hit++; }
  });
  if (phrase) return phrase + sum;
  return hit >= need ? sum : 0;
}
/* every entry that fits the search, best first (an empty search returns the list as it is).
   When no entry has every word, the result holds the half-matches and is marked .loose */
function searchGlossary(list, q){
  const qn = glNorm(q);
  if (!qn) return list.slice();
  const qc = qn.replace(/ /g, '');
  let qw = glWords(qn);
  const kept = qw.filter(w => !GL_STOP.includes(w[0]));
  if (kept.length) qw = kept;
  const memo = new Map();
  const run = (need, wide) => {
    const out = [];
    list.forEach(e => { const s = glScore(e.ix || glPrepare(e), qn, qc, qw, need, wide, memo); if (s > 0) out.push([s, e]); });
    out.sort((a, b) => b[0] - a[0] || a[1].term.localeCompare(b[1].term));
    return out.map(x => x[1]);
  };
  let res = run(qw.length, false);
  if (!res.length) res = run(qw.length, true);
  if (!res.length && qw.length > 1){
    res = run(Math.ceil(qw.length / 2), true);
    res.loose = true;
  }
  return res;
}
/* for a search with no match: up to n words whose names are close to what was typed.
   The word's own name counts most, then the words inside it, then its other names. */
function glSuggest(list, q, n){
  const qn = glNorm(q);
  if (qn.length < 3) return [];
  const qc = qn.replace(/ /g, ''), qs = glSound(qc);
  const lim = Math.max(2, Math.floor(qn.length / 3));
  const out = [];
  list.forEach(e => {
    const ix = e.ix || glPrepare(e);
    let d = 99;
    const names = [[ix.tc, 0]].concat(ix.tw.map(w => [w[0], 0.4]), ix.ac.map(c => [c, 0.8]), ix.aw.map(w => [w[0], 1.2]));
    names.forEach(nm => {
      const c = nm[0];
      if (c.length < 3 || !glAlike(qc, c)) return;
      const dist = glSound(c) === qs ? 1 : glDist(qc, c, lim);
      if (dist <= lim) d = Math.min(d, dist + nm[1]);
    });
    if (d < 99) out.push([d, e]);
  });
  out.sort((a, b) => a[0] - b[0] || a[1].term.localeCompare(b[1].term));
  return out.slice(0, n || 3).map(x => x[1]);
}
