const TP_FLAG_MIN = 3;
const TP_UNITS = [1, 2, 5, 10, 25, 50, 100, 250, 500, 1000];
const TP_FAMILY_ORDER = ['Fruit', 'Floral', 'Sweet', 'Nutty and cocoa', 'Spice', 'Roasted', 'Green and earthy', 'Fermented', 'Basic tastes', 'Off-flavors'];
/* the smallest unit (1 bean = unit coffees) that keeps the tallest pile at cap beans or fewer */
function tpUnit(max, cap){ cap = cap || 12; return TP_UNITS.find(u => max / u <= cap) || 1000; }
function tpHue(family){ const f = FLAVOR_WHEEL.find(x => x.name === family); return f ? f.hue : null; }
/* One pile of beans for each whole star. Half stars count with the whole star above in the piles (the counts), as everywhere else. The middle (the flag) and the middle half are worked out on the real ratings,
   so a 2.5 is not pushed up to a 3 before the middle is found. They show from 3 coffees. */
function tpHeap(stars){
  const counts = [0, 0, 0, 0, 0], raw = (stars || []).map(s => Math.min(5, Math.max(1, +s || 1))), bin = raw.map(s => Math.min(5, Math.max(1, Math.ceil(s - 1e-9))));
  bin.forEach(b => { counts[b - 1]++; });
  const n = raw.length, s = raw.slice().sort((a, b) => a - b), enough = n >= TP_FLAG_MIN;
  return { counts, n, enough, median:enough ? tpMedian(s) : null, band:enough ? [s[Math.floor((n - 1) * 0.25)], s[Math.min(n - 1, Math.round((n - 1) * 0.75))]] : null, max:Math.max(0, ...counts) };
}
/* ---------- wheel colors: every family gets its own clear color ---------- */
const FAM_COLORS = {
  'Fruit':'#C2255C', 'Floral':'#7B3FA3', 'Sweet':'#F2A93B', 'Nutty and cocoa':'#7A4A2A', 'Spice':'#C2461A', 'Roasted':'#3F4B57',
  'Green and earthy':'#2F7D32', 'Off-smells':'#1D4E89', 'Basic tastes':'#1A7F8E', 'Fermented':'#B7A92F', 'Off-flavors':'#1D4E89',
  'Sweet finish':'#F2A93B', 'Clean finish':'#1A7F8E', 'Fruity and floral':'#C2255C', 'Chocolate and nut':'#7A4A2A', 'Spice and toast':'#C2461A',
  'Smoky and roasty':'#3F4B57', 'Dry and puckery':'#B08D57', 'Bitter and harsh':'#6B2737', 'Sour and sharp':'#7CB518', 'Fades quickly':'#6F18AA',
  /* mouthfeel wheel */
  'Weight':'#2A6F97', 'Smooth':'#E0952B', 'Rough':'#5E7A4B', 'Dry':'#A23B2A',
  /* what-do-I-change wheel: one color for each of the four groups the Perfect step uses */
  'Weak, sharp or faint':'#2A6F97', 'Harsh or heavy':'#6B2737', 'Odd or inconsistent':'#C2461A', 'Nothing to fix':'#F2A93B'
};
const WHEEL_INK = '#1B2B2A';
function whRgb(h){ return [1, 3, 5].map(i => parseInt(h.slice(i, i + 2), 16)); }
function whLum(h){ const f = v => { v /= 255; return v <= 0.03928 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4); }, c = whRgb(h); return 0.2126 * f(c[0]) + 0.7152 * f(c[1]) + 0.0722 * f(c[2]); }
function whContrast(a, b){ const x = whLum(a), y = whLum(b); return (Math.max(x, y) + 0.05) / (Math.min(x, y) + 0.05); }
function whMix(h, w){ return '#' + whRgb(h).map(v => Math.round(v * (1 - w) + 255 * w).toString(16).padStart(2, '0')).join(''); }
function whInk(h){ return whContrast(h, '#FFFFFF') >= whContrast(h, WHEEL_INK) ? '#FFFFFF' : WHEEL_INK; }
function whHsl(h, s, l){ s /= 100; l /= 100; const k = n => (n + h / 30) % 12, a = s * Math.min(l, 1 - l), f = n => l - a * Math.max(-1, Math.min(k(n) - 3, Math.min(9 - k(n), 1))); return '#' + [f(0), f(8), f(4)].map(x => Math.round(x * 255).toString(16).padStart(2, '0')).join(''); }
function whPalette(fam){
  const fill = fam.color || FAM_COLORS[fam.name] || whHsl(fam.hue || 200, 52, 38);
  let sel = whMix(fill, 0.3);
  for (const w of [0.3, 0.25, 0.35, 0.2, 0.4, 0.15, 0.45, 0.1, 0.5]){ const t = whMix(fill, w); if (whContrast(t, whInk(t)) >= 4.5){ sel = t; break; } }
  let mid = fill;   /* a slightly lighter shade for alternate slices, as light as the text on it allows */
  for (const w of [0.22, 0.18, 0.14, 0.1, 0.06]){ const t = whMix(fill, w); if (whContrast(t, whInk(t)) >= 4.5){ mid = t; break; } }
  return { fill, ink:whInk(fill), mid, midInk:whInk(mid), tintA:whMix(fill, 0.62), tintB:whMix(fill, 0.78), tintSel:sel, selInk:whInk(sel) };
}
function whFit(txt, radial, arc, max){
  const byArc = arc * 0.62, byLen = radial / (Math.max(1, String(txt).length) * 0.58);
  return Math.round(Math.max(7.5, Math.min(max, byArc, byLen)) * 10) / 10;
}

/* Share `total` degrees among slices by weight, none under `min` degrees (unless they cannot all fit, then equal). */
function whSpread(weights, total, min){
  const n = weights.length; if (!n) return [];
  if (min * n >= total) return weights.map(() => total / n);
  if (!(weights.reduce((s, w) => s + (w > 0 ? w : 0), 0) > 0)) return weights.map(() => total / n);   /* all weights zero: share evenly rather than divide by zero */
  const fixed = new Array(n).fill(false), out = new Array(n).fill(0);
  for (let pass = 0; pass < n; pass++){
    let sw = 0, left = total; weights.forEach((w, i) => { if (fixed[i]) left -= out[i]; else sw += w; });
    let again = false;
    weights.forEach((w, i) => { if (fixed[i]) return; out[i] = left * w / sw; if (out[i] < min){ out[i] = min; fixed[i] = true; again = true; } });
    if (!again) break;
  }
  return out;
}
/* Every wheel in one shape: { title, center, fams:[{ name, short, hue, groups:[{ name, full (the whole name, when the slice shows a short one), words:[{ t (the word), n (a kit vial number, if any) }] }] }] }.
   The data lists hold words as text, or as { n, name } for the aroma kit; an empty word list is allowed (the what-do-I-change wheel has only two rings). */
function whNorm(title, center, data){
  return { title:title, center:center, fams:data.map(f => ({ name:f.name, short:f.short, hue:f.hue, color:f.color, sym:f.sym,
    groups:f.groups.map(g => ({ name:g[0], full:g[3] || g[0], pat:g[2] || null, words:g[1].map(w => typeof w === 'string' ? { t:w } : { t:w.name, n:w.n }) })) })) };
}
/* why a field changes nothing in the recipe numbers; each one is checked by the tests, which change the field and rebuild every recipe */
const PAGE_NONE = {
  process:'Washed is the baseline reference process, so grind, temperature and ratio stay at baseline unless a honey, natural or experimental ferment tier is selected.',
  density:'Mid elevation (1,200–1,500 m) is the baseline reference density, so temperature stays at baseline.',
  decaf:'Regular caffeinated porosity is the baseline reference; decaf and half-caf adjust grind and temperature automatically when selected.',
  origin:'Shapes your bag guide, latitude-adjusted seed density, and default process/elevation hints when left blank.',
  varietal:'Standard Bourbon/Caturra cultivar baseline; micro-fines or giant-screen varietals (such as Ethiopian landraces, Gesha, or Pacamara) adjust grind and thermal targets when selected.',
  blend:'Stops guessing a blend\'s process or elevation from a single origin.',
  bag_notes:'Helps rank brewer pairings and shapes your flavor guide without overriding physical brew targets.',
  name:'Saved with your tastings and shown on the page. Name and roaster never change your brew settings.',
  roast_medium:'Medium is the baseline reference point, so nothing moves.',
  roast_unset:'Not set, so we assumed medium. Lighter or darker roasts adjust grind, temperature, and target ratio.',
  roast_date:'Inside its peak resting window for this roast, so bloom and extraction targets need no CO2 or age compensation.'
};
const pagePlural = (n, w) => n + ' ' + w + (n === 1 ? '' : 's');
/* the difference between the recipe with a field and without it: what moved in the numbers, and what only shows up as a tip or a warning */
function pageParts(a, b){
  const moved = [], shown = [];
  const gs = a.grind.shift - b.grind.shift;
  if (gs) moved.push('grind ' + (Math.abs(gs) === 0.5 ? 'half a step' : Math.abs(gs) === 1 ? 'one step' : pagePlural(Math.abs(gs), 'step')) + (gs > 0 ? ' finer' : ' coarser'));
  if (a.temp.kind === 'hot' && b.temp.kind === 'hot' && a.temp.f !== b.temp.f){ const d = a.temp.f - b.temp.f; moved.push('water ' + Math.abs(d) + '°F (' + Math.abs(Math.round(fToC(a.temp.f) - fToC(b.temp.f))) + '°C) ' + (d > 0 ? 'hotter' : 'cooler')); }
  if (a.ratio !== b.ratio) moved.push('ratio ' + fmtRatio(a.ratio) + ' instead of ' + fmtRatio(b.ratio));
  if (a.bloom && b.bloom && a.bloom.secs !== b.bloom.secs) moved.push('bloom ' + a.bloom.secs + ' seconds instead of ' + b.bloom.secs);
  if (a.ratioSuggest && !b.ratioSuggest) shown.push('a suggested ratio of ' + fmtRatio(a.ratioSuggest.ratio) + ' that you can choose to use');
  const tips = r => (r.temp.layers || []).filter(l => /tip$/i.test(l.k)).length;
  if (tips(a) > tips(b)) shown.push('a water temperature tip');
  const had = new Set((b.risks || []).map(x => x.title)), add = (a.risks || []).filter(x => !had.has(x.title));
  if (add.length) shown.push('a warning ("' + add[0].title + '")');
  return { moved, shown };
}
const pageList = l => l.length < 3 ? l.join(' and ') : l.slice(0, -1).join(', ') + ' and ' + l[l.length - 1];
/* one row per thing the person set on the coffee page: { key, label, value, kind:'moved' | 'shown' | 'none', text } */
function pageEffects(coffee, methodKey, batch, now){
  const c = coffee || {}, m = METHODS.find(x => x.key === methodKey);
  if (!m) return { rows:[], moved:0, shown:0, none:0 };
  const own = Object.assign({}, batch || {}); ['tempF', 'ratio', 'tempComp', 'grinderKey', 'calib'].forEach(k => { delete own[k]; });   /* the recommended recipe, not the person's own overrides */
  const rec = x => buildRecipe(x, methodKey, own, null, now), fit = x => (methodAdvice(x, now).find(y => y.key === methodKey) || {});
  const rows = [];
  const blank = Object.assign({}, c, { origin:'' });          /* origin cleared on both sides, so a field is judged without the guess the origin would make */
  function row(key, label, value, without, base, reason, shownReason){
    const a = rec(base), b = rec(without), p = pageParts(a, b), fa = fit(base), fb = fit(without);
    const fitMoved = fa.tier && fb.tier && fa.tier !== fb.tier ? 'It moved ' + m.label + ' from "' + fb.tierLabel + '" to "' + fa.tierLabel + '" on the method screen.' : '';
    let kind, text;
    if (p.moved.length){ kind = 'moved'; text = pageList(p.moved).replace(/^./, s => s.toUpperCase()) + ', compared with leaving it out.' + (p.shown.length ? ' It also adds ' + pageList(p.shown) + '.' : ''); }
    else if (p.shown.length){ kind = 'shown'; text = 'Nothing in the numbers. It adds ' + pageList(p.shown) + '.' + (shownReason === undefined ? ' ' + reason : shownReason ? ' ' + shownReason : ''); }
    else { kind = 'none'; text = reason; }
    if (fitMoved && kind !== 'moved') { text += ' ' + fitMoved; if (kind === 'none') kind = 'shown'; }
    else if (fitMoved) text += ' ' + fitMoved;
    rows.push({ key, label, value, kind, text: text.trim() });
  }
  const p0 = profileOf(c, now);
  if (c.roast){
    row('roast', 'Roast level', labelOf(ROASTS, c.roast), Object.assign({}, blank, { roast:'' }), blank, PAGE_NONE.roast_medium);
    const r = rows[rows.length - 1]; if (r.kind === 'moved') r.text += ' The grind shift is common practice, not a tested rule.';
  } else rows.push({ key:'roast', label:'Roast level', value:'Not set', kind:'none', text:PAGE_NONE.roast_unset });
  if (c.roast_date && p0.days != null) row('roast_date', 'Roast date', c.roast_date + ' (' + pagePlural(p0.days, 'day') + ' old)', Object.assign({}, blank, { roast_date:'' }), blank, PAGE_NONE.roast_date, '');
  if (c.process) row('process', 'Process', labelOf(PROCESSES, c.process), Object.assign({}, blank, { process:'' }), blank, PAGE_NONE.process, 'Sources disagree on which way process should move the grind, temperature or ratio, so the suggestions are optional and nothing is changed for you.');
  if (c.density) row('density', 'Elevation', labelOf(DENSITIES, c.density), Object.assign({}, blank, { density:'' }), blank, PAGE_NONE.density);
  if (c.decaf === 'yes') row('decaf', 'Decaf', 'Yes', Object.assign({}, blank, { decaf:'' }), blank, PAGE_NONE.decaf);
  if (c.origin) row('origin', 'Origin', c.origin, blank, c, PAGE_NONE.origin);
  if (c.blend === 'blend') row('blend', 'Blend', 'Yes', Object.assign({}, c, { blend:'' }), c, PAGE_NONE.blend);
  if (c.varietal) row('varietal', 'Varietal', c.varietal, Object.assign({}, c, { varietal:'' }), c, PAGE_NONE.varietal);
  if (c.bag_notes) row('bag_notes', 'Tasting notes', String(c.bag_notes).slice(0, 60), Object.assign({}, c, { bag_notes:'' }), c, PAGE_NONE.bag_notes);
  rows.push({ key:'name', label:'Name and roaster', value:[c.name, c.roaster].filter(Boolean).join(' · '), kind:'none', text:PAGE_NONE.name });
  return { rows, moved:rows.filter(x => x.kind === 'moved').length, shown:rows.filter(x => x.kind === 'shown').length, none:rows.filter(x => x.kind === 'none').length };
}

/* ---------- Adaptive Palate Intelligence Engine v5.0 (5-Axis Radar, LCB80 Leaderboards, Signed Flavor Affinity & Bullseye/Bridge/Horizon) ---------- */
const PALATE_AXES = [
  { key:'acidity',    label:'Acidity',    short:'Acidity',    lo:'Mellow / Low-Acid', hi:'Vibrant / Juicy' },
  { key:'sweetness',  label:'Sweetness',  short:'Sweetness',  lo:'Dry / Crisp',       hi:'Lush / Caramel-Fruit' },
  { key:'body',       label:'Body',       short:'Body',       lo:'Tea-Like / Silky',  hi:'Syrupy / Velvety' },
  { key:'bitterness', label:'Bitterness', short:'Roast Depth',lo:'Zero Roast Bite',   hi:'Dark Cocoa / Roasty' },
  { key:'clarity',    label:'Clarity',    short:'Clarity',    lo:'Wild / Funky / Blend', hi:'Laser-Clean Terroir' }
];

function palateCupIntensities(o){
  let ij = null;
  try { if (o && o.cva_intensity_json) ij = JSON.parse(o.cva_intensity_json); } catch(e){}
  const num = v => { const n = parseFloat(v); return Number.isFinite(n) && n >= 1 && n <= 5 ? n : null; };
  const rawRoast = o && (o.roast || o.roast_level);
  const rawProc = o && o.process;
  const rk = (typeof resolveRoast === 'function' && resolveRoast(rawRoast)) || tendKey(ROASTS, rawRoast);
  const pk = (typeof resolveProcess === 'function' && resolveProcess(rawProc)) || tendKey(PROCESSES, rawProc);
  const roastIdx = { 'ultra-light':0, light:1, 'medium-light':2, medium:3, 'medium-dark':4, dark:5 }[rk];
  const isHoney = pk === 'honey' || /-honey$/.test(pk);
  const isFerm = pk === 'anaerobic' || pk === 'carbonic' || pk === 'thermal-shock' || pk === 'yeast-koji' || pk === 'infused';
  const acidPrior = roastIdx != null ? [4.5, 4.1, 3.6, 3.0, 2.3, 1.8][roastIdx] : 3.0;
  const bodyPrior = (roastIdx != null ? [2.0, 2.3, 2.7, 3.1, 3.6, 4.0][roastIdx] : 3.0) + (pk === 'natural' || pk === 'wet-hulled' || pk === 'black-honey' ? 0.4 : isHoney || isFerm ? 0.2 : pk === 'washed' ? -0.2 : 0);
  const sweetPrior = (pk === 'natural' || isHoney || isFerm) ? 3.8 : (roastIdx === 2 || roastIdx === 3) ? 3.5 : 3.1;
  const bitPrior = roastIdx != null ? [1.2, 1.6, 2.1, 2.8, 3.7, 4.4][roastIdx] : 2.7;
  const clarPrior = pk === 'washed' ? 4.2 : (pk === 'white-honey' || pk === 'yellow-honey') ? 3.7 : isHoney ? 3.3 : (pk === 'natural' || pk === 'wet-hulled' || isFerm) ? 2.5 : 3.1;
  const clamp5 = x => Math.max(1, Math.min(5, x));
  const pick3 = (a, b, c) => a != null ? a : (b != null ? b : c);
  return {
    acidity:    pick3(num(o && o.acidity_intensity),    ij ? num(ij.acidity) : null,    clamp5(acidPrior)),
    sweetness:  pick3(num(o && o.sweetness_intensity),  ij ? num(ij.sweetness) : null,  clamp5(sweetPrior)),
    body:       pick3(num(o && o.body_intensity),       ij ? num(ij.mouthfeel != null ? ij.mouthfeel : ij.body) : null, clamp5(bodyPrior)),
    bitterness: pick3(num(o && o.bitterness_intensity), ij ? num(ij.bitterness) : null, clamp5(bitPrior)),
    clarity:    pick3(num(o && o.clarity_intensity),    ij ? num(ij.clarity) : null,    clamp5(clarPrior)),
    measured: !!(num(o && o.acidity_intensity) || num(o && o.body_intensity) || num(o && o.sweetness_intensity) || ij)
  };
}

function palateSeedAxes(seed){
  const s = seed || {};
  const ac = s.acid === 'bright' ? 78 : s.acid === 'low' ? 28 : 54;
  const bo = s.body === 'rich' ? 76 : s.body === 'light' ? 32 : 54;
  const bi = s.roast === 'dark' ? 74 : s.roast === 'light' ? 26 : 48;
  const cl = s.vibe === 'clean' ? 80 : s.vibe === 'funky' ? 36 : 58;
  const sw = s.vibe === 'sweet' || s.vibe === 'fruity' ? 76 : 62;
  return { acidity:ac, sweetness:sw, body:bo, bitterness:bi, clarity:cl };
}

function palateArchetypeOf(axesMap, topOrigin, topProcess){
  const a = axesMap.acidity || 50, s = axesMap.sweetness || 50, b = axesMap.body || 50, bit = axesMap.bitterness || 50, cl = axesMap.clarity || 50;
  if (a >= 64 && cl >= 62) return { title:'High-Clarity Terroir Seeker', sub:'You gravitate toward vibrant, sparkling acidity and transparent washed or floral lots where individual fruit and tea notes shine.' };
  if (s >= 64 && b >= 58 && cl < 58) return { title:'Lush Fruit & Honey Explorer', sub:'You reward jammy sweetness, rounded mouthfeel, and expressive natural or honey-processed coffees.' };
  if (bit >= 62 && b >= 60) return { title:'Velvet Cocoa & Roast Traditionalist', sub:'You enjoy comforting dark-chocolate depth, syrupy weight, and low-acid balance across medium-to-dark roasts.' };
  if (s >= 60 && a >= 45 && a < 64) return { title:'Sweet-Balanced All-Rounder', sub:'Your highest ratings cluster around caramel-sweet harmony where crisp fruit and smooth chocolate stay in equilibrium.' };
  return { title:'Curious Specialty Calibrator', sub:'Your palate spans multiple styles' + (topOrigin ? ' — led so far by ' + topOrigin : '') + (topProcess ? ' (' + topProcess + ')' : '') + ' as your sensory map sharpens.' };
}

/* Empirical Bayes LCB80 Leaderboard builder:
   theta_hat = (S_g + kappa * mu_0) / (W_g + kappa), LCB80 = theta_hat - 0.8416 * s_0 / sqrt(W_g + kappa) */
function palateLeaderboard(items, extractGroups, mu0, s0, kappa){
  kappa = kappa || 3.0;
  const groups = {};
  items.forEach(it => {
    const gs = extractGroups(it) || [];
    gs.forEach(g => {
      if (!g || !g.key) return;
      const rec = groups[g.key] || (groups[g.key] = { key:g.key, label:g.label || g.key, sub:g.sub || '', w:0, sum:0, n:0, topN:0, vals:[], names:[] });
      const w = Number.isFinite(it.weight) ? it.weight : 1;
      rec.w += w;
      rec.sum += w * it.val;
      rec.n += 1;
      if (it.isTop) rec.topN += 1;
      rec.vals.push(it.val);
      if (it.name && rec.names.length < 4 && rec.names.indexOf(it.name) < 0) rec.names.push(it.name);
    });
  });
  return Object.keys(groups).map(k => {
    const g = groups[k];
    const postMean = (g.sum + kappa * mu0) / (g.w + kappa);
    const se = s0 / Math.sqrt(g.w + kappa);
    const lcb80 = postMean - 0.8416 * se;
    const rawMean = g.vals.reduce((a, b) => a + b, 0) / g.vals.length;
    return {
      key:g.key, label:g.label, sub:g.sub, n:g.n, topN:g.topN,
      rawMean:Math.round(rawMean * 100) / 100,
      postMean:Math.round(postMean * 100) / 100,
      lcb80:Math.round(lcb80 * 100) / 100,
      delta:Math.round((postMean - mu0) * 100) / 100,
      conf:Math.min(1, g.n / 5),
      names:g.names
    };
  }).sort((a, b) => b.lcb80 - a.lcb80 || b.n - a.n || a.label.localeCompare(b.label));
}

function computePalateAnalytics(historyRows, setup, now){
  const objs = Array.isArray(historyRows) ? historyRows.map(r => Array.isArray(r) ? rowToObj(r) : r).filter(Boolean) : [];
  const coffees = prefCoffees(objs);
  const ratedCoffees = coffees.filter(c => c.stars > 0);
  const cupUnits = prefCups(objs).filter(u => u.stars > 0);
  const nCoffees = ratedCoffees.length, nCups = objs.length;
  const tier = nCoffees === 0 ? 0 : nCoffees <= 3 ? 1 : nCoffees <= 9 ? 2 : 3;
  const tierMeta = [
    { tier:0, code:'seed',       label:'Seed Profile (0 Coffees)',     nextNeed:4,  desc:'Answer 3 quick palate prompts below or log your first cup to initialize your 5-Axis Palate DNA.' },
    { tier:1, code:'early',      label:'Early Signal (' + nCoffees + ' of 4 Coffees)', nextNeed:4 - nCoffees, desc:'Provisional sensory signal active — log ' + (4 - nCoffees) + ' more ' + (4 - nCoffees === 1 ? 'coffee' : 'coffees') + ' to unlock full Palate DNA & Buyer\'s Fit.' },
    { tier:2, code:'emerging',   label:'Emerging Palate (' + nCoffees + ' Coffees)',   nextNeed:10 - nCoffees, desc:'Empirical Bayes shrinkage active — ' + (10 - nCoffees) + ' more ' + (10 - nCoffees === 1 ? 'coffee unlocks' : 'coffees unlock') + ' high-confidence Calibrated status.' },
    { tier:3, code:'calibrated', label:'Calibrated Palate (' + nCoffees + ' Coffees)', nextNeed:0, desc:'Full Empirical Bayes LCB80 leaderboards, collinearity correction, and Smart Bag Guide active.' }
  ][tier];

  const vals = ratedCoffees.map(c => c.stars);
  const wSum = ratedCoffees.reduce((a, c) => a + (c.weight || 1), 0);
  const mu0 = wSum > 0 ? ratedCoffees.reduce((a, c) => a + (c.weight || 1) * c.stars, 0) / wSum : 3.75;
  const muRef = 0.60 * mu0 + 0.40 * 3.25; /* damped reference so generous raters still reveal high-axis lean! */
  const rawSd = vals.length > 1 ? Math.sqrt(vals.reduce((a, v) => a + (v - mu0) * (v - mu0), 0) / (vals.length - 1)) : 0.55;
  const s0 = Math.max(0.45, rawSd);
  const asc = vals.slice().sort((a, b) => a - b);
  const tauTop = vals.length >= 3 ? Math.max(4.0, Math.round(prefQuantile(asc, 0.67) * 100) / 100) : 4.0;

  /* 1. 5-Axis Palate DNA Radar (5..95) */
  const seedMap = palateSeedAxes(setup && setup.palateSeed);
  const axesMap = {};
  let measuredIntensityCups = 0;
  const cupIntRows = [];
  objs.forEach(o => {
    const st = prefCupStarEq(o);
    if (!(st > 0)) return;
    const ci = palateCupIntensities(o);
    if (ci.measured) measuredIntensityCups++;
    cupIntRows.push({ st, ci });
  });
  PALATE_AXES.forEach(ax => {
    if (!cupIntRows.length){
      axesMap[ax.key] = setup && setup.palateSeed ? seedMap[ax.key] : 50;
      return;
    }
    let num = 0, den = 3.0; /* kappa_radar = 3.0 */
    cupIntRows.forEach(r => {
      const likingPull = (r.st - muRef) / 1.75; /* [-1.3 .. +1.0] */
      const centeredAttr = (r.ci[ax.key] - 3.0) / 2.0; /* [-1 .. +1] */
      /* Reward high attribute level when cup is liked above damped ref, and invert when disliked */
      const signal = centeredAttr * (0.55 + likingPull);
      num += signal;
      den += 1;
    });
    const rawScore = 50 + 42 * (num / den);
    const blended = tier === 1 && setup && setup.palateSeed ? 0.55 * rawScore + 0.45 * seedMap[ax.key] : rawScore;
    axesMap[ax.key] = Math.round(Math.max(8, Math.min(94, blended)));
  });
  const radarAxes = PALATE_AXES.map(ax => ({ key:ax.key, label:ax.label, short:ax.short, lo:ax.lo, hi:ax.hi, score:axesMap[ax.key] }));

  /* 2. LCB80 Leaderboards */
  const lbItems = ratedCoffees.map(c => ({
    val:c.stars, weight:c.weight || 1, isTop:c.stars >= tauTop, name:c.name, c
  }));
  const originsBoard = palateLeaderboard(lbItems, it => it.c.place && it.c.place.country ? [{ key:it.c.place.country, label:it.c.place.country, sub:it.c.place.region }] : [], mu0, s0, 2.5);
  const areasBoard = palateLeaderboard(lbItems, it => it.c.place && it.c.place.area ? [{ key:it.c.place.country + ':' + it.c.place.area, label:it.c.place.area, sub:it.c.place.country }] : [], mu0, s0, 2.0);
  const processesBoard = palateLeaderboard(lbItems, it => it.c.process ? [{ key:it.c.process, label:prefLabel('process', it.c.process) }] : [], mu0, s0, 2.5);
  const roastsBoard = palateLeaderboard(lbItems, it => it.c.roast ? [{ key:it.c.roast, label:prefLabel('roast', it.c.roast) }] : [], mu0, s0, 2.5);
  const varietalsBoard = palateLeaderboard(lbItems, it => it.c.variety ? [{ key:it.c.variety, label:it.c.variety }] : [], mu0, s0, 2.5);
  const coffeesBoard = ratedCoffees.slice().map(c => {
    const post = (c.stars * Math.min(3, c.cups) + 1.5 * mu0) / (Math.min(3, c.cups) + 1.5);
    return { key:c.key, label:c.name, sub:c.roaster || (c.place ? c.place.country : ''), n:c.cups, rawMean:c.stars, postMean:Math.round(post * 100) / 100, lcb80:Math.round((post - 0.5 * s0 / Math.sqrt(c.cups + 1.5)) * 100) / 100, brewFaultOnly:c.brewFaultOnly };
  }).sort((a, b) => b.rawMean - a.rawMean || b.lcb80 - a.lcb80);

  const brewerItems = cupUnits.map(u => ({ val:u.stars, weight:1, isTop:u.stars >= tauTop, name:u.name, u }));
  const brewersBoard = palateLeaderboard(brewerItems, it => it.u.brewer ? [{ key:it.u.brewer, label:prefLabel('brewer', it.u.brewer) }] : [], mu0, s0, 2.5);

  /* 3. Signed Liked-vs-Disliked Flavor Family Affinity A_f in [-100, +100] */
  const famAcc = {}, subAcc = {};
  ratedCoffees.forEach(c => {
    const zc = Math.max(-1, Math.min(1, (c.stars - muRef) / Math.max(0.45, s0)));
    const famsSeen = {}, subsSeen = {};
    (c.dislikedWords || []).forEach(w => {
      const info = tpWordInfo(w);
      if (info && !info.feel && info.family && info.family !== TP_OTHER){
        famsSeen[info.family] = Math.min(famsSeen[info.family] || 0, -1.25);
        if (info.sub) subsSeen[info.family + ' · ' + info.sub] = -1.25;
      }
    });
    (c.likedWords || []).forEach(w => {
      const info = tpWordInfo(w);
      if (info && !info.feel && info.family && info.family !== TP_OTHER && !(info.family in famsSeen)){
        famsSeen[info.family] = 1.0;
        if (info.sub) subsSeen[info.family + ' · ' + info.sub] = 1.0;
      }
    });
    const hasExplicitTags = (c.likedWords && c.likedWords.length > 0) || (c.dislikedWords && c.dislikedWords.length > 0);
    if (!hasExplicitTags){
      (c.words || []).forEach(w => {
        if (w.family && !(w.family in famsSeen)) famsSeen[w.family] = 0.55 * zc;
        if (w.sub && !((w.family + ' · ' + w.sub) in subsSeen)) subsSeen[w.family + ' · ' + w.sub] = 0.55 * zc;
      });
    }
    Object.keys(famsSeen).forEach(f => {
      const rec = famAcc[f] || (famAcc[f] = { family:f, sum:0, n:0, likedN:0, dislikedN:0 });
      rec.sum += famsSeen[f]; rec.n += 1;
      if (famsSeen[f] > 0.15) rec.likedN++; else if (famsSeen[f] < -0.15) rec.dislikedN++;
    });
    Object.keys(subsSeen).forEach(sk => {
      const rec = subAcc[sk] || (subAcc[sk] = { key:sk, sum:0, n:0 });
      rec.sum += subsSeen[sk]; rec.n += 1;
    });
  });
  const flavorAffinities = Object.keys(famAcc).map(f => {
    const r = famAcc[f], score = Math.round(Math.max(-100, Math.min(100, 100 * r.sum / (r.n + 2.5))));
    return { family:f, score, n:r.n, likedN:r.likedN, dislikedN:r.dislikedN, color:FAM_COLORS[f] || '#8B5A2B' };
  }).sort((a, b) => b.score - a.score || b.n - a.n);
  const subFlavorAffinities = Object.keys(subAcc).filter(k => subAcc[k].n >= 2).map(k => {
    const r = subAcc[k];
    return { label:k, score:Math.round(Math.max(-100, Math.min(100, 100 * r.sum / (r.n + 2.0)))), n:r.n };
  }).sort((a, b) => b.score - a.score);

  /* 4. Brew-Fault vs Bean-Dislike Disentanglement Summary */
  const brewFaultCoffees = ratedCoffees.filter(c => c.brewFaultOnly);
  const archetype = palateArchetypeOf(axesMap, originsBoard[0] && originsBoard[0].label, processesBoard[0] && processesBoard[0].label);

  return {
    tier, tierMeta, nCoffees, nCups, measuredIntensityCups,
    mu0:Math.round(mu0 * 100) / 100, s0:Math.round(s0 * 100) / 100, tauTop,
    archetype, radarAxes, axesMap,
    boards:{ origins:originsBoard, areas:areasBoard, processes:processesBoard, roasts:roastsBoard, varietals:varietalsBoard, brewers:brewersBoard, coffees:coffeesBoard },
    flavorAffinities, subFlavorAffinities,
    brewFaultCoffees:brewFaultCoffees.map(c => ({ name:c.name, roaster:c.roaster, stars:c.stars, symptom:c.objs[0] && c.objs[0].fix_symptom }))
  };
}

/* Smart Bag Buyer's Guide + Bullseye / Bridge / Horizon Recommendation Slots */
const BAG_ARCHETYPE_CATALOG = [
  { id:'eth-washed-light', title:'Washed Ethiopian Yirgacheffe / Guji', roast:'light', process:'washed', origin:'Ethiopia', varietal:'Heirloom', notes:'Jasmine, bergamot, lemon, peach', tags:['Light Roast', 'Washed', 'Ethiopia', 'Floral & Citrus'] },
  { id:'ken-washed-light', title:'Washed Kenyan SL28 / SL34 (Nyeri or Kirinyaga)', roast:'light', process:'washed', origin:'Kenya', varietal:'SL28', notes:'Blackcurrant, ruby grapefruit, hibiscus, cane sugar', tags:['Light Roast', 'Washed', 'Kenya', 'Juicy Berry-Citrus'] },
  { id:'col-pink-bourbon', title:'Colombian Huila / Nariño Washed Pink Bourbon', roast:'medium-light', process:'washed', origin:'Colombia', varietal:'Pink Bourbon', notes:'Sweet orange, apricot, honey, panela', tags:['Medium-Light', 'Washed', 'Colombia', 'Sweet Stone-Fruit'] },
  { id:'eth-nat-fruity', title:'Natural Ethiopian Guji / Sidama', roast:'light', process:'natural', origin:'Ethiopia', varietal:'Heirloom', notes:'Blueberry, strawberry jam, milk chocolate, tropical fruit', tags:['Light Roast', 'Natural', 'Ethiopia', 'Lush Berry'] },
  { id:'crc-honey-sweet', title:'Costa Rica Tarrazú Red / Yellow Honey', roast:'medium-light', process:'honey', origin:'Costa Rica', varietal:'Catuai', notes:'Caramel, yellow plum, roasted almond, honey', tags:['Medium-Light', 'Honey', 'Costa Rica', 'Silky Caramel-Fruit'] },
  { id:'gua-washed-med', title:'Guatemalan Huehuetenango / Antigua Balanced Washed', roast:'medium', process:'washed', origin:'Guatemala', varietal:'Bourbon', notes:'Milk chocolate, toffee, baked apple, hazelnut', tags:['Medium Roast', 'Washed', 'Guatemala', 'Chocolate & Crisp Apple'] },
  { id:'bra-pulped-nutty', title:'Brazilian Cerrado / Sul de Minas Pulped Natural', roast:'medium', process:'honey', origin:'Brazil', varietal:'Mundo Novo', notes:'Hazelnut, dark cocoa, brown sugar, nougat', tags:['Medium Roast', 'Pulped Natural', 'Brazil', 'Low-Acid Nut & Cocoa'] },
  { id:'sum-wethulled-rich', title:'Sumatra Mandheling / Gayo Wet-Hulled', roast:'medium-dark', process:'wet-hulled', origin:'Indonesia', varietal:'Typica', notes:'Dark chocolate, cedar, sweet clove, syrupy body', tags:['Medium-Dark', 'Wet-Hulled', 'Indonesia', 'Syrupy & Spiced'] },
  { id:'pan-gesha-floral', title:'High-Elevation Panama / Peru Washed Gesha', roast:'light', process:'washed', origin:'Panama', varietal:'Gesha', notes:'Orange blossom, jasmine tea, mandarin, honeydew', tags:['Light Roast', 'Washed', 'Panama', 'Ultra-Clean Floral'] },
  { id:'col-ea-decaf', title:'Colombian Sugarcane (EA) Specialty Decaf', roast:'medium', process:'washed', origin:'Colombia', varietal:'Castillo', notes:'Caramel, milk chocolate, sweet orange, graham cracker', tags:['Medium Roast', 'Sugarcane Decaf', 'Colombia', 'Evening Sweet Balance'] }
];

function computeSmartBagGuide(historyRows, candidateBag, analytics){
  const objs = Array.isArray(historyRows) ? historyRows.map(r => Array.isArray(r) ? rowToObj(r) : r).filter(Boolean) : [];
  const pal = analytics || computePalateAnalytics(objs, null);
  const cand = candidateBag || {};
  const fit = prefFit(objs, {
    id:cand.id || '', name:cand.name || '', roaster:cand.roaster || '',
    roast:cand.roast || '', process:cand.process || '', density:cand.density || '',
    origin:cand.origin || '', varietal:cand.varietal || '', bag_notes:cand.bag_notes || cand.notes || '', blend:cand.blend || ''
  }, 'stars');
  const verdict = fitVerdict(fit), summary = fitLine(fit);

  /* Score catalog archetypes to pick Bullseye, Bridge, and Horizon! */
  const topRoast = pal.boards.roasts[0] ? pal.boards.roasts[0].key : (pal.axesMap.bitterness >= 60 ? 'medium-dark' : pal.axesMap.acidity >= 62 ? 'light' : 'medium-light');
  const topProc = pal.boards.processes[0] ? pal.boards.processes[0].key : (pal.axesMap.clarity >= 62 ? 'washed' : 'honey');
  const triedOrigins = new Set(pal.boards.origins.map(o => o.key.toLowerCase()));

  const scored = BAG_ARCHETYPE_CATALOG.map(entry => {
    const f = prefFit(objs, { roast:entry.roast, process:entry.process, origin:entry.origin, varietal:entry.varietal, bag_notes:entry.notes }, 'stars');
    const roastMatch = entry.roast === topRoast ? 12 : 0;
    const procMatch = entry.process === topProc ? 10 : 0;
    const novelOrigin = !triedOrigins.has(entry.origin.toLowerCase());
    const score = (Number.isFinite(f.pct) ? f.pct : 50) + roastMatch + procMatch;
    return { entry, fit:f, score, roastMatch:!!roastMatch, procMatch:!!procMatch, novelOrigin };
  }).sort((a, b) => b.score - a.score);

  const bullseye = scored[0];
  const bridge = scored.find(x => x !== bullseye && (x.roastMatch || x.procMatch) && (x.novelOrigin || x.entry.process !== bullseye.entry.process || x.entry.origin !== bullseye.entry.origin)) || scored[1] || scored[0];
  const horizon = scored.slice().reverse().find(x => x !== bullseye && x !== bridge && x.entry.id !== 'col-ea-decaf') || scored[scored.length - 1];

  const recommendations = [
    { slot:'bullseye', badge:'Bullseye · Safe Bet', icon:'target', title:bullseye.entry.title, tags:bullseye.entry.tags, notes:bullseye.entry.notes, pct:bullseye.fit.pct, why:'Aligns directly with your highest-rated roast, process, and flavor tendencies.' },
    { slot:'bridge',   badge:'Bridge · Smart Discovery', icon:'compass', title:bridge.entry.title, tags:bridge.entry.tags, notes:bridge.entry.notes, pct:bridge.fit.pct, why:'Keeps your favorite roast/process anchor while introducing a rewarding new origin or fruit profile.' },
    { slot:'horizon',  badge:'Horizon · Palate Stretch', icon:'globe', title:horizon.entry.title, tags:horizon.entry.tags, notes:horizon.entry.notes, pct:horizon.fit.pct, why:'A contrasting specialty style that calibrates your sensory map and tests new flavor territory.' }
  ];

  return {
    fit, verdict, summary,
    matchPct:Number.isFinite(fit.pct) ? fit.pct : 50,
    lo:Number.isFinite(fit.lo) ? fit.lo : 35,
    hi:Number.isFinite(fit.hi) ? fit.hi : 65,
    unexplored:!!fit.unexplored,
    badge:fit.badge || verdict.word,
    recommendations
  };
}

