/* ---------- known coffees and did you mean ----------
   Only the person's own coffees and roasters are used for typo suggestions, never overriding without explicit consent. */
const knownNorm = s => String(s == null ? '' : s).toLowerCase().replace(/[^\p{L}\p{N}]+/gu, ' ').trim();
function knownCoffees(hist, prices){
  const m = new Map();
  const put = (coffee, roaster, date) => {
    coffee = priceText(coffee, 80); roaster = priceText(roaster, 80); if (!coffee) return;
    const k = knownNorm(coffee) + '|' + knownNorm(roaster);
    if (!m.has(k)) m.set(k, { coffee, roaster, n:0, last:'' });
    const e = m.get(k); e.n++; if (String(date || '') > e.last) e.last = String(date || '');
  };
  (hist || []).forEach(o => put(o.coffee_name, o.roaster, o.cupping_date));
  (prices || []).forEach(e => put(e.coffee, e.roaster, e.date));
  return Array.from(m.values()).sort((a, b) => b.n - a.n || b.last.localeCompare(a.last) || a.coffee.localeCompare(b.coffee));
}
const knownTol = n => n <= 3 ? 0 : n <= 5 ? 1 : n <= 9 ? 2 : 3;
function didYouMean(typed, known){
  const c = knownNorm(typed && typed.coffee), r = knownNorm(typed && typed.roaster), list = Array.isArray(known) ? known : [];
  if ((!c && !r) || !list.length) return null;
  const near = (a, b) => { const t = knownTol(Math.max(a.length, b.length)); return a !== b && t > 0 && levWithin(a, b, t) <= t; };
  const same = list.filter(k => knownNorm(k.coffee) === c);
  if (c && same.length){
    if (!r){ const top = same.find(k => k.roaster); return top ? { kind:'roaster', coffee:top.coffee, roaster:top.roaster, fixCoffee:false, fixRoaster:true } : null; }
    if (same.some(k => knownNorm(k.roaster) === r)) return null;
    const cand = same.filter(k => k.roaster && near(knownNorm(k.roaster), r));
    return cand.length ? { kind:'fixRoaster', coffee:cand[0].coffee, roaster:cand[0].roaster, fixCoffee:false, fixRoaster:true } : null;
  }
  if (c){
    const cand = list.filter(k => near(knownNorm(k.coffee), c) && (!r || knownNorm(k.roaster) === r || near(knownNorm(k.roaster), r)))
      .map(k => ({ k, d:levWithin(knownNorm(k.coffee), c, 9) })).sort((a, b) => a.d - b.d || b.k.n - a.k.n);
    if (cand.length){ const k = cand[0].k; return { kind:'fixCoffee', coffee:k.coffee, roaster:k.roaster, fixCoffee:true, fixRoaster:!!k.roaster && knownNorm(k.roaster) !== r }; }
  }
  if (r){
    const cand = list.filter(k => k.roaster && near(knownNorm(k.roaster), r)).sort((a, b) => b.n - a.n);
    if (cand.length && !list.some(k => knownNorm(k.roaster) === r)) return { kind:'fixRoaster', coffee:c ? priceText(typed.coffee, 80) : '', roaster:cand[0].roaster, fixCoffee:false, fixRoaster:true };
  }
  return null;
}
