  cupMl:[200, 350], cupMm:[75, 90],              /* 5.2.1: cups of tempered glass or ceramic, 200 to 350 mL, top diameter 75 to 90 mm, all identical */
  waterC:93, waterTol:3,                         /* 7.3: water at 93 +/- 3 C, poured to the rim */
