  L.push('For: ' + (SCA_PURPOSE[s.purpose] ? SCA_PURPOSE[s.purpose].name : 'not chosen') + '. ' + s.n + ' coffees, ' + s.cups + ' cups of each' + (s.same ? ' (the same coffee, cups that differ)' : '') + '.');
