const ORIGIN_NOT_A_TYPO = new Set(['colombo', 'columbus', 'mocha', 'liberica', 'indiana', 'dominica', 'bananas']);   /* real words that sit one letter from a country: a Mocha drink is not Yemen, Liberica is a species, Indiana is a state */
