const releaseLatest = () => RELEASES[0];
/* a release time for people: in the reader's own time zone when the time is known, else the date alone. opts.timeZone and opts.locale exist for the tests. */
function releaseWhen(r, opts){
  opts = opts || {};
  if (!r) return { text:'', hasTime:false };
  try {
    if (r.at){
      const f = new Intl.DateTimeFormat(opts.locale || undefined, { year:'numeric', month:'short', day:'numeric', hour:'numeric', minute:'2-digit', timeZoneName:'short', timeZone:opts.timeZone || undefined });
      return { text:f.format(new Date(r.at)), hasTime:true };
    }
    const f2 = new Intl.DateTimeFormat(opts.locale || undefined, { year:'numeric', month:'short', day:'numeric', timeZone:'UTC' });
    return { text:f2.format(new Date(r.date + 'T12:00:00Z')), hasTime:false };
  } catch(e){ return { text:r.at || r.date || '', hasTime:!!r.at }; }
}

