function originOptions(){
  const groups = [['Latin America and the Caribbean', 'latam', 'Latin America'], ['Africa', 'africa', 'Africa'], ['Asia-Pacific', 'asia', 'Asia-Pacific'], ['Arabian Peninsula', 'arabia', 'Arabian Peninsula']];
  return groups.map(([label, key, oreg]) => {
    const items = [];
    ORIGINS.forEach(o => { if (o.key !== 'africa' && (o.region === oreg || (key === 'latam' && o.region === 'Caribbean'))) items.push({ value:o.key === 'hawaii' ? 'Hawaii' : o.name, label:o.key === 'hawaii' ? 'Hawaii (USA)' : o.name, full:true }); });
    COFFEE_COUNTRIES.forEach(c => { if (!c.general && c.region === key) items.push({ value:c.name, label:c.name, full:false }); });
    items.sort((a, b) => a.label.localeCompare(b.label));
    return { group:label, items };
  }).filter(g => g.items.length);
}

/* Country-level regexes (never regions!) so apostrophes ('Hawai\'i') & acronyms ('PNG', 'DRC') strip cleanly without duplicating or eating region names */
const COUNTRY_STRIP_RE = {
  'Hawaii':[/\bhawai['\u2018\u2019\u02BB\u02BC]?i(?:an)?(?:\s*\(\s*usa\s*\))?/gi],
  'Papua New Guinea':[/\bpapua\s+new\s+guinea(?:n)?\b/gi, /\bpng\b/gi],
  'Democratic Republic of the Congo':[/\bdemocratic\s+republic\s+of\s+(?:the\s+)?congo\b/gi, /\bd\.?\s*r\.?\s*congo\b/gi, /\bdrc\b/gi, /\bcongolese\b/gi, /\bcongo\b/gi],
  'Ivory Coast':[/\bivory\s+coast\b/gi, /\bc[oô]te\s+d['\u2018\u2019\u02BB\u02BC\s]?ivoire\b/gi, /\bivorian\b/gi],
  'Timor-Leste':[/\btimor[\s\-]+leste\b/gi, /\beast\s+timor\b/gi, /\btimorese\b/gi],
  'Myanmar':[/\bmyanmar\b/gi, /\bburma\b/gi, /\bburmese\b/gi],
  'Costa Rica':[/\bcosta\s+rica(?:n)?\b/gi],
  'El Salvador':[/\bel\s+salvador\b/gi, /\bsalvador(?:an|ian)\b/gi],
  'Dominican Republic':[/\bdominican\s+republic\b/gi, /\brep[uú]blica\s+dominicana\b/gi, /\bdominican\b/gi],
  'Puerto Rico':[/\bpuerto\s+ric(?:o|an)\b/gi],
  'La Réunion':[/\b(?:la\s+)?r[eé]union\b/gi, /\bbourbon\s+island\b/gi],
  'Trinidad and Tobago':[/\btrinidad(?:\s+and\s+tobago)?\b/gi]
};

/* Apostrophe- and acronym-safe parseOrigin (fixes BUG-INP-06: "Kona, Hawai'i" -> { countries:['Hawaii'], rest:'Kona' }, "Wahgi, PNG" -> { countries:['Papua New Guinea'], rest:'Wahgi' }) */
function parseOrigin(text){
  const t = String(text || '').trim(); if (!t) return { countries:[], rest:'', other:false };
  const deApos = t.replace(/([A-Za-z\u00C0-\u017F])['\u2018\u2019\u02BB\u02BC]([A-Za-z\u00C0-\u017F])/g, '$1$2');
  const m = (typeof originMatch === 'function' && originMatch(deApos)) || {}; let names = [];
  if (m.many) names = m.many.slice();
  else if (m.origin) names = [m.origin.key === 'hawaii' ? 'Hawaii' : m.origin.name];
  else if (m.country && !m.country.general) names = [m.country.name];
  if (!names.length) return { countries:[], rest:t, other:true };

  const stripLastRe = (str, rx) => {
    const g = new RegExp(rx.source, rx.flags.indexOf('g') >= 0 ? rx.flags : rx.flags + 'g');
    let mm, last = null;
    while ((mm = g.exec(str))){
      const before = mm.index > 0 ? str[mm.index - 1] : ' ';
      const after = str[mm.index + mm[0].length] || ' ';
      if (!/[A-Za-z0-9]/.test(before) && !/[A-Za-z0-9]/.test(after)) last = mm;
      if (g.lastIndex === mm.index) g.lastIndex++;
    }
    return last ? str.slice(0, last.index) + ' ' + str.slice(last.index + last[0].length) : str;
  };

  /* Order multi-country matches by first appearance */
  const lowT = norm(deApos);
  const pos = {};
  names.forEach(n => {
    const keyLow = norm(n);
    const idx = lowT.indexOf(keyLow);
    pos[n] = idx >= 0 ? idx : 9999;
  });
  names.sort((x, y) => pos[x] - pos[y]);

  let rest = t;
  names.forEach(n => {
    const custom = COUNTRY_STRIP_RE[n] || [];
    custom.forEach(rx => { rest = stripLastRe(rest, rx); });
    /* Also strip plain country name and close demonyms (e.g. Colombia/Colombian, Peru/Peruvian, Brazil/Brasil/Brazilian) */
    const o = ORIGINS.find(x => x.name === n || (n === 'Hawaii' && x.key === 'hawaii'));
    const c = COFFEE_COUNTRIES.find(x => x.name === n);
    const baseNorm = norm(n).replace(/[^a-z0-9 ]+/g, ' ').replace(/\s+/g, ' ').trim();
    const coreWords = [n];
    ((o ? o.aliases : c ? c.aliases : []) || []).forEach(al => {
      const an = norm(al).replace(/[^a-z0-9 ]+/g, ' ').replace(/\s+/g, ' ').trim();
      if (an && (an === baseNorm || an.indexOf(baseNorm) === 0 || lev(an, baseNorm) <= 2)) coreWords.push(al);
    });
    if (m.fuzzy && m.fuzzy.typed && names.length === 1) coreWords.push(m.fuzzy.typed);
    coreWords.sort((a, b) => b.length - a.length).forEach(w => {
      const pat = w.trim().split(/\s+/).map(part => {
        /* Allow optional accents and internal apostrophes on letters */
        return escRe(norm(part)).replace(/[aeiou]/g, ch => ({ a:'[aàáâãäåā]', e:'[eèéêëē]', i:"[iìíîïī'\\u2019\\u02BB]*i?", o:'[oòóôõöō]', u:'[uùúûüū]' })[ch]);
      }).join('[\\s\\-]+');
      try { rest = stripLastRe(rest, new RegExp(pat, 'gi')); } catch(e){}
    });
  });

  rest = rest.replace(/\(\s*\)/g, ' ').replace(/\b(?:and|&)\b/gi, ',').split(/[,;/|•]+/).map(x => x.replace(/^[\s(\-–—]+|[\s)\-–—]+$/g, '')).filter(Boolean).join(', ');
  return { countries:names, rest, other:false };
}

function composeOrigin(countries, extra, blend){
  const e = String(extra || '').trim();
  if (!blend && e && countries[0] && norm(e).includes(norm(countries[0]))) return e;
  return blend ? countries.concat(e ? [e] : []).join(', ') : (e ? e + ', ' : '') + (countries[0] || '');
}
function originMismatch(country, rest){
  const r = String(rest || '').trim(); if (!r || !country) return null;
  const m = originMatch(r, { fuzzy:false }), other = m.origin ? (m.origin.key === 'hawaii' ? 'Hawaii' : m.origin.name) : (m.country && !m.country.general ? m.country.name : null);
  return other && other !== country ? { region:r, country:other } : null;
}

