const VARIETY_SPLIT = /[,;/&+]|\band\b/i;
function parseVarietal(text){
  const picked = [], other = [];
  String(text || '').split(VARIETY_SPLIT).map(x => x.trim()).filter(Boolean).forEach(tk => {
    const n = String(norm(tk)).replace(/[^a-z0-9 ]+/g, ' ').replace(/\s+/g, ' ').trim();
    const ch = VARIETY_CHOICES.find(c => c.alias.includes(n) || String(norm(c.label)) === n || String(norm(c.text)) === n);
    if (ch){ if (!picked.includes(ch.label)) picked.push(ch.label); } else other.push(tk);
  });
  picked.sort((a, b) => VARIETY_CHOICES.findIndex(c => c.label === a) - VARIETY_CHOICES.findIndex(c => c.label === b));
  return { picked, other:other.join(', ') };
}
function composeVarietal(picked, other){ return VARIETY_CHOICES.filter(c => picked.includes(c.label)).map(c => c.text).concat(other ? [other] : []).join(', '); }
function varietiesFor(text){
  const out = [], seen = new Set();
  String(text || '').split(VARIETY_SPLIT).forEach(tk => { const v = varietyFor(tk.trim()); if (v && !seen.has(v.name)){ seen.add(v.name); out.push(v); } });
  return out;
}

/* ---------- solid or folklore ----------
   Every entry says what people say, gives one verdict, and shows what was found, what it does not show, what BeanTelligence does about it, and the sources.
   Rules the logic test enforces: each entry has a tier, a one-line verdict, at least one finding, at least one limit and at least one source, and every source says what kind it is.
   A finding states only what the source itself reports. When a source was read only through someone else's summary, the finding says so ("as summarized by ...").
   The verdict is about the claim as people phrase it, not about the whole subject. One study is never called proof. */
const FOLK_TIERS = {
  solid:{ label:'Solid', text:'Measured in controlled tests or published as a standard, and the finding holds as stated.' },
  partly:{ label:'Partly supported', text:'Some evidence behind it, with limits worth knowing.' },
  practice:{ label:'Practice only', text:'Common among brewers, but we found no controlled test of it.' },
  not:{ label:'Not supported', text:'The research we found does not back it, or points the other way.' }
};
const FOLK_KINDS = { paper:'Peer-reviewed paper', poster:'Conference poster, not peer reviewed', article:'Trade or news article', blog:'A company\'s or brewer\'s own test, not peer reviewed' };
