/* Build Unified 72+ VARIETALS List preserving all VARIETY_CHOICES (68) + VARIETIES (40) descriptions */
const VARIETALS = [];
(function buildUnifiedVarietals(){
  const seen = {};
  (VARIETY_CHOICES || []).forEach(vc => {
    const vName = vc.name || vc.label || vc.text || '';
    const k = norm(vName).replace(/[^a-z0-9]+/g, '');
    if (!k || seen[k]) return;
    seen[k] = true;
    const matchDesc = (VARIETIES || []).find(v => v.key === k || norm(v.name) === norm(vName) || (v.aliases || []).some(a => norm(a) === norm(vName)));
    VARIETALS.push({
      key:k,
      name:vName,
      label:vc.label || vName,
      group:vc.group || 'Arabica Cultivars',
      hint:vc.hint || (matchDesc ? matchDesc.text : ''),
      text:matchDesc ? matchDesc.text : (vc.hint || vc.text || vName),
      aliases:Array.from(new Set([norm(vName)].concat(vc.alias || [], matchDesc ? (matchDesc.aliases || []) : []))),
      alias:vc.alias || []
    });
  });
  (VARIETIES || []).forEach(v => {
    const k = v.key || norm(v.name).replace(/[^a-z0-9]+/g, '');
    if (seen[k]) return;
    seen[k] = true;
    VARIETALS.push({
      key:k,
      name:v.name,
      label:v.name,
      group:'Specialty Cultivars',
      hint:v.text,
      text:v.text,
      aliases:v.aliases || [norm(v.name)],
      alias:v.aliases || []
    });
  });
})();

