const LESSONS = LESSON_ORDER.map((id, idx) => {
  const raw = LESSONS_MAP[id] || {};
  const rate = raw.rate || (id === 'family' || id === 'species' ? 'A' : 'B');
  const epTier = rate === 'A' ? 'verified_science' : rate === 'C' ? 'active_research' : 'craft_best_practice';
  const rawBadge = typeof G.epistemicBadgeFor === 'function' ? G.epistemicBadgeFor(epTier) : null;
  const badge = (rawBadge && typeof rawBadge === 'object') ? (rawBadge.badge || '[Verified Science]') : (typeof rawBadge === 'string' && rawBadge ? rawBadge : '[Verified Science]');
  return Object.assign({ id, key:id, order:idx + 1, rate, epistemicTier:epTier, badge, epistemicMeta:rawBadge && typeof rawBadge === 'object' ? rawBadge : null }, raw);
});
LESSONS.forEach(item => {
  Object.defineProperty(LESSONS, item.id, { value:item, enumerable:false, configurable:true });
});
if (LESSONS_MAP.roasting && !LESSONS.roast) {
  Object.defineProperty(LESSONS, 'roast', { value:LESSONS.roasting, enumerable:false, configurable:true });
}

